; ----------------------------------------------------------------
; Keyboard check & pause toggle handler
; Checks for Ctrl-T to toggle pause flag at $50
; Falls through to main keyboard dispatch at UP ($7318)
; ----------------------------------------------------------------

KBDCHECK:
        LDA KEYBOARD                ; read keyboard hardware register
        CMP #$94                    ; is it Ctrl-T (toggle pause)?
        BEQ KBDGOT                  ; yes, toggle pause mode
        LDA PAUSEFLAG               ; check current pause state
        BEQ KBDNOPAUSE              ; if not paused, check joystick
        BNE KBDCONT                 ; if paused, check keyboard only

; Toggle pause on/off
KBDGOT:
        STA KBDSTRB                 ; clear keyboard strobe
        LDA PAUSEFLAG               ; get current pause state
        EOR #$FF                    ; flip all bits (toggle)
        STA PAUSEFLAG               ; store new pause state
        BNE KBDCONT                 ; if now paused, check keyboard

; Not paused - check joystick input then movement
KBDNOPAUSE:
        JSR CHKL                    ; check joystick/paddle input
        JMP MOVEEND                 ; process movement and return

; Paused or post-toggle - read keyboard for movement keys
KBDCONT:
        LDA KEYBOARD                ; read keyboard register
        JMP KBDDISPATCH             ; jump to key handler


