; ----------------------------------------------------------------
; PAGESWITCH - Toggle double-buffer page variable
; Flips PAGEFLIP between $00 and $60 (HGR page 1 vs page 2)
; Also toggles $63 for auxiliary tracking
; ----------------------------------------------------------------
PAGESWITCH:
        LDA PAGEFLIP                ; get current page ($00 or $60)
        EOR #$60                    ; flip: $00->$60 or $60->$00
        STA PAGEFLIP                ; store new draw page
        LDA $63                     ; get auxiliary page flag
        EOR #$01                    ; toggle 0<->1
        STA $63                     ; store new flag
        RTS

; ----------------------------------------------------------------
; SELECTPAGE - Switch HGR display to match PAGEFLIP
; If PAGEFLIP=$00: display page 1 (LOWSCR)
; If PAGEFLIP=$60: display page 2 (HISCR)
; ----------------------------------------------------------------
SELECTPAGE:
        LDA PAGEFLIP                ; check which page to display
        BNE SELPAGE2                ; if non-zero, show page 2
        LDA LOWSCR                  ; switch to page 1 ($2000)
        RTS

SELPAGE2:
        LDA HISCR                   ; switch to page 2 ($4000)
        RTS

; ----------------------------------------------------------------
; DELAY1 - Short delay (2 iterations × $14 cycles)
; Uses Apple II ROM WAIT routine at $FCA8
; ----------------------------------------------------------------
DELAY1:
        LDY #$02                    ; 2 iterations
DELAY1LP:
        LDA #$14                    ; delay value (short)
        JSR WAIT                    ; ROM: delay A×2.5 microseconds
        DEY                         ; next iteration
        BNE DELAY1LP                ; loop until done
        RTS

; ----------------------------------------------------------------
; DELAY2 - Longer delay (3 iterations × $41 cycles)
; Uses Apple II ROM WAIT routine at $FCA8
; ----------------------------------------------------------------
DELAY2:
        LDY #$03                    ; 3 iterations
DELAY2LP:
        LDA #$41                    ; delay value (longer)
        JSR WAIT                    ; ROM: delay A×2.5 microseconds
        DEY                         ; next iteration
        BNE DELAY2LP                ; loop until done
        RTS

        LDY $8F8D
L_6F84:
        LDA #$19
        JSR WAIT                    ; $FCA8
        DEY
        BNE L_6F84
        RTS

        ORA (SHAPE,X)               ; $10
        ORA $49
        .BYTE $FF                                  ; |#######|
        CLC
        ADC #$01
        RTS


; ----------------------------------------------------------------
; Low-level sprite drawing with shift/mask (XOR blit)
; Uses SCANLINE ($56) and PAGEFLIP ($62) for double buffering
; ----------------------------------------------------------------

SPRITEDRAW:
        LDX #$00
        LDY SCANLINE                ; $56
        LDA $8D52,Y
        STA SCRLO                   ; $59
        LDA $8E12,Y
        EOR PAGEFLIP                ; $62
        STA SCRHI                   ; $5A
        LDY $57
        LDA $8AD0,Y
        STA $5C
        LDA $8BE8,Y
        TAY
        LDA $9D1F,X
        AND #$80
        STA $6B
        LDA $9D1F,X
        AND #$7F
        STA $64
        LDA #$00
        STA $68
        LDA $5C
        CMP #$01
        BEQ L_6FDE
L_6FC9:
        LSR $64
        ROR $68
        ASL $5C
        BIT $5C
        BPL L_6FC9
        LSR $68
        LDA $68
        ORA $6B
        EOR (SCRLO),Y               ; $59
        STA (SCRLO),Y               ; $59
        INY
L_6FDE:
        LDA $64
        ORA $6B
        EOR (SCRLO),Y               ; $59
        STA (SCRLO),Y               ; $59
        INC SCANLINE                ; $56
        INX
        CPX #$04
        BCS L_6FF0
        JMP HGRDATA2                ; $8F98

L_6FF0:
        RTS

        STA $8FB2
        STA $8FB9
        STY $8FB3
        STY $8FBA
        RTS

        .BYTE $20, $60, $4C, $DD, $76              ; |.....#......##..##..##.###.#.##.###|

; ----------------------------------------------------------------
; Data tables for enemies
; HITBL     - hit/collision flags per enemy type
; CATBTBL   - direction flip masks for boundary bounces
;             (XOR to reverse: $01=horiz, $06=vert, $07=both)
; PLACESX/Y - spawn position tables for cats (8 positions)
; ----------------------------------------------------------------

HITBL:
        .BYTE $00, $00, $00, $00, $FF, $00, $00, $00 ; |............................#######.....................|
        .BYTE $FF                                  ; |#######|
        .BYTE $FF                                  ; |#######|
        .BYTE $00
        .BYTE $00
        .BYTE $FF                                  ; |#######|
        .BYTE $FF                                  ; |#######|
        .BYTE $FF                                  ; |#######|
        .BYTE $00
CATBTBL:
        .BYTE $01, $06, $07                        ; |#.......##....###....|
PLACESX:
        .BYTE $14, $28, $70, $50, $28, $14, $50, $70 ; |..#.#.....#.#.....###....#.#...#.#...#.#......#.#....###|
PLACESY:
        .BYTE $50, $A0, $50, $A0, $80, $90, $80, $90 ; |....#.#.....#.....#.#.....#............#.............#..|

; ----------------------------------------------------------------
; Sound routines
; CLICK - Short speaker click for feedback
; ORPLOTS - OR-plot with coordinate conversion
; ----------------------------------------------------------------
CLICK:
        LDA SOUND                   ; check sound enabled
        BMI ORPLOTS                 ; bit 7 = muted, skip click
        STA SPKR                    ; toggle speaker
ORPLOTS:
        ; OR-plot with X coordinate conversion (byte to pixel)
        LDA X                       ; get byte position
        PHA                         ; save it
        ASL A                       ; multiply by 4
        ASL A                       ; convert to pixel X
        STA X                       ; set pixel coordinate
        JSR ORPLOT                  ; OR-plot to screen
        PLA                         ; restore byte position
        STA X                       ;
        RTS                         ; return

PLOTS:
        LDA X                       ; $18
        PHA
        ASL A
        ASL A
        STA X                       ; $18
        JSR PLOT                    ; $7A09
        PLA
        STA X                       ; $18
        RTS


; ----------------------------------------------------------------
; BORDER - Game screen initialization
; Sets up the playing field borders, switches to hi-res mode,
; and draws the game title text using CHRGEN
; ----------------------------------------------------------------

BORDER:
        JSR HOME                    ; clear text screen (ROM)
        STA LOWSCR                  ; display page 1
        STA TXTSET                  ; enable text mode briefly
        JSR CLRSCRN                 ; clear HGR screen to black
        STA TXTSET                  ; ensure text visible during setup

        ; Start drawing from bottom-right corner
        LDA #$BF                    ; Y = 191 (bottom row)
        STA Y                       ;
        LDA #$26                    ; X = 38 (near right edge)
        STA X                       ;
        LDA #$55                    ; green color pattern
        STA COLOR                   ;

; Draw top border (right to left)
BORDER1:
        JSR ORPLOTS                 ; plot pixel
        DEC Y                       ; move up one row
        JSR ORPLOTS                 ; plot double-height border
        INC Y                       ; move back down
        LDA COLOR                   ; alternate colors
        EOR #$7F                    ; toggle between green/violet
BORDER2:
        STA COLOR                   ; set new color
        DEC X                       ; move left
        BNE BORDER1                 ; loop until left edge
        JSR ORPLOTS                 ; final pixel

        ; Draw left border (bottom to top)
        LDA #$15                    ; color pattern for left side
        STA COLOR                   ;
L_707F:
        JSR ORPLOTS                 ; plot pixel
        DEC Y                       ; move up
        LDA Y                       ; check position
        CMP #$11                    ; reached top yet?
        BCS L_707F                  ; no, continue up

        ; Draw bottom border (left to right)
        LDA #$55                    ; green color pattern
        STA COLOR                   ;
L_708E:
        JSR ORPLOTS                 ; plot pixel
        INC Y                       ; move down
BORDER4:
        JSR ORPLOTS                 ; plot double-height
        DEC Y                       ; move back up
        LDA COLOR                   ; alternate colors
        EOR #$7F                    ; toggle green/violet
        STA COLOR                   ; set new color
        INC X                       ; move right
        LDA X                       ; check position
        CMP #$26                    ; reached right edge?
        BNE L_708E                  ; no, continue right
        JSR ORPLOTS                 ; final pixel

        ; Draw right border (top to bottom)
        LDA #$54                    ; color for right side
        STA COLOR                   ;
L_70AD:
        JSR ORPLOTS                 ; plot pixel
        INC Y                       ; $19
        LDA Y                       ; $19
        CMP #$BF                    ; '?' key
        BCC L_70AD
        LDA #$27
        STA XX                      ; $1A
        LDA #$00
        STA YY                      ; $1B
        LDA #$00
        STA WIDTH                   ; $1C
        LDA #$01
        STA HEIGHT                  ; $1D
        LDA #$FF
        STA COLORMASK               ; $03
        LDA #$14
        JSR CHRGEN                  ; $9000
        LDA #$08
        STA YY                      ; $1B
        LDA #$09
        JSR CHRGEN                  ; $9000
        LDA #$10
        STA YY                      ; $1B
        LDA #$0D
        JSR CHRGEN                  ; $9000
        LDA #$18
        STA YY                      ; $1B
        LDA #$05
        JSR CHRGEN                  ; $9000
        LDA #$21
        STA TIME                    ; $8D
        LDA #$D5
        STA COLOR                   ; $11
        LDA TIME                    ; $8D
        STA Y                       ; $19
        LDA #$27
        STA X                       ; $18
L_70FC:
        JSR PLOTS                   ; $703B
        INC Y                       ; $19
        LDA Y                       ; $19
        CMP #$BF                    ; '?' key
        BCC L_70FC
        STA TXTCLR                  ; $C050
        STA HIRES                   ; $C057
        STA MIXCLR                  ; $C052
NOJOY:
        RTS

; ----------------------------------------------------------------
; CHKL - Check joystick/paddle for movement input
; Reads paddle buttons PB0/PB1/PB2 - if all pressed, skip
; Alternates reading X and Y paddles based on JOYFLG toggle
; Paddle value < $30 = left/up, > $D0 = right/down
; ----------------------------------------------------------------
CHKL:
        LDA PB0                     ; read paddle button 0
        AND PB1                     ; AND with button 1
        AND PB2                     ; AND with button 2
        BMI L_712F                  ; if all pressed (bit7=1), skip input

; Check which paddle axis to read (alternates each frame)
CHKUPDO:
        LDA JOYFLG                  ; get toggle flag
        BMI L_7130                  ; if negative, read X first
        EOR #$FF                    ; toggle flag
        STA JOYFLG                  ; store new toggle
        JSR READPADDLE              ; read Y paddle (up/down)
        LDA #$30                    ; short delay
        JSR WAIT                    ; wait for paddle settle
        JSR MOVRI                   ; read X paddle (left/right)
L_712F:
        RTS

; Alternate order: read X paddle first, then Y
L_7130:
        EOR #$FF                    ; toggle flag
        STA JOYFLG                  ; store new toggle
        JSR MOVRI                   ; read X paddle first
        LDA #$30                    ; short delay
        JSR WAIT                    ; wait for paddle settle
        JSR READPADDLE              ; read Y paddle
        RTS

; ----------------------------------------------------------------
; READPADDLE - Read Y paddle (paddle 1) for up/down movement
; Input: paddle 1 via PREAD ROM routine
; If value < $30: move up, > $D0: move down
; ----------------------------------------------------------------
READPADDLE:
        LDX #$01                    ; select paddle 1 (Y axis)
        JSR PREAD                   ; ROM: read paddle, returns in Y
        TYA                         ; transfer value to A
        CMP #$30                    ; paddle pushed up? (<$30)
MOVDO:
        BCC DEC2                    ; yes, move up
        CMP #$D0                    ; paddle pushed down? (>=$D0)
        BCS L_716C                  ; yes, move down
        RTS                         ; centered, no movement

; ----------------------------------------------------------------
; MOVRI - Read X paddle (paddle 0) for left/right movement
; Input: paddle 0 via PREAD ROM routine
; If value < $30: move left, > $D0: move right
; ----------------------------------------------------------------
MOVRI:
        LDX #$00                    ; select paddle 0 (X axis)
        JSR PREAD                   ; ROM: read paddle, returns in Y
        TYA                         ; transfer value to A
        CMP #$30                    ; paddle pushed left? (<$30)
        BCC L_7165                  ; yes, move left
        CMP #$D0                    ; paddle pushed right? (>=$D0)
        BCS L_7173                  ; yes, move right
        RTS                         ; centered, no movement

; Paddle up - pop 2 return addresses and jump to move up handler
DEC2:
        PLA                         ; pop return address 1 (low)
        PLA                         ; pop return address 1 (high)
        PLA                         ; pop return address 2 (low)
        PLA                         ; pop return address 2 (high)
        JMP DOMOVUP                 ; execute upward movement

; Paddle left - pop 2 return addresses and jump to move left handler
L_7165:
        PLA                         ; pop return addresses
        PLA
        PLA
        PLA
        JMP DOMOVLE                 ; execute leftward movement

; Paddle down - pop 2 return addresses and jump to move down handler
L_716C:
        PLA                         ; pop return addresses
        PLA
        PLA
        PLA
        JMP DOMOVDO                 ; execute downward movement

; Paddle right - pop 2 return addresses and jump to move right handler
L_7173:
        PLA                         ; pop return addresses
        PLA
        PLA
        PLA
        JMP DOMOVRI                 ; execute rightward movement

; ----------------------------------------------------------------
; SOUNDTICK - Timer tick with sound and time decrement
; Generates ticking sound while counting down TIME
; Returns carry set if time expired
; ----------------------------------------------------------------
SOUNDTICK:
        LDY #$32                    ; 50 iterations outer loop
L_717C:
        ; Calculate delay based on remaining time
        LDA #$C0                    ; max delay base
        SBC TIME                    ; subtract current time
        LSR A                       ; divide by 2
        TAX                         ; X = delay count
L_7182:
        DEX                         ; inner delay loop
        BNE L_7182                  ; wait
        LDA SOUND                   ; check sound enabled
DEC3:
        BMI PUTSCORE                ; bit 7 = sound off, skip
        STA SPKR                    ; toggle speaker (tick sound)

; ----------------------------------------------------------------
; Score and status display routines
; Uses BCD format and NUMGEN for digit rendering
; ----------------------------------------------------------------
; PUTSCORE - Decrement time and check for timeout
PUTSCORE:
        DEY                         ; decrement outer loop
        BNE L_717C                  ; continue ticking
        LDA #$00                    ; prepare for time decrement
        STA COLOR                   ; $11
        LDA #$27
        STA X                       ; $18
        LDA TIME                    ; $8D
        STA Y                       ; $19
        JSR PLOTS                   ; $703B
        INC TIME                    ; $8D
        LDA TIME                    ; $8D
        AND #$1F
        BNE L_71AB
        INC NUMCATS                 ; $90
        JSR CATRI                   ; $7522
L_71AB:
        LDA TIME                    ; $8D
        CMP #$BF                    ; '?' key
        RTS

; ----------------------------------------------------------------
; SHOWSCORE - Display 5-digit BCD score at top of screen
; Score format: SCOREHI1 (1 digit) + SCOREHI (2 digits) + SCORELO (2 digits)
; Each digit rendered at X positions $0F, $11, $13, $15, $17
; Uses NUMGEN for digit rendering
; ----------------------------------------------------------------
SHOWSCORE:
        LDA SCOREHI1                ; get highest score byte
        AND #$0F                    ; extract low nibble (digit 1)
        STA SHAPE                   ; digit value = shape index
        LDA #$0F                    ; X position for digit 1
        STA XX                      ; set draw X
        LDA #$00                    ; Y position = top row
        STA YY                      ; set draw Y
        LDA #$FF                    ; white color
        STA COLORMASK               ; set color mask
        JSR NUMGEN                  ; draw first digit
        LDA SCOREHI                 ; get middle score byte
        LSR A                       ; shift right 4 times
        LSR A                       ; to get high nibble
        LSR A
        LSR A
        STA SHAPE                   ; high nibble = digit 2
        LDA #$11                    ; X position for digit 2
        STA XX
        JSR NUMGEN                  ; draw second digit
        LDA SCOREHI                 ; reload middle byte
        AND #$0F                    ; extract low nibble (digit 3)
        STA SHAPE
        LDA #$13                    ; X position for digit 3
        STA XX
        JSR NUMGEN                  ; draw third digit
        LDA SCORELO                 ; get low score byte
        LSR A                       ; shift to get high nibble
        LSR A
        LSR A
        LSR A
        STA SHAPE                   ; digit 4
        LDA #$15                    ; X position
        STA XX
        JSR NUMGEN                  ; draw fourth digit
        LDA SCORELO                 ; reload low byte
        AND #$0F                    ; low nibble = digit 5
        STA SHAPE
        LDA #$17                    ; X position for digit 5
        STA XX
        JSR NUMGEN                  ; draw fifth digit
        CLC                         ; clear carry (success)
        RTS

; ----------------------------------------------------------------
; SHOWLEVEL - Display "LIVES" text and lives count at top-left
; Uses CHRGEN for each character: L=12, I=9, V=22, E=5, S=19
; Then displays lives count as digit using NUMGEN
; ----------------------------------------------------------------
SHOWLEVEL:
        LDA #$00                    ; start at X=0
        STA XX
        STA YY                      ; Y=0 (top of screen)
        LDA #$00                    ; character width = 0
        STA WIDTH
        LDA #$01                    ; character height = 1
        STA HEIGHT
        LDA #$FF                    ; white color
        STA COLORMASK
        LDA #$0C                    ; char 12 = 'L'
        JSR CHRGEN                  ; draw 'L'
        INC XX                      ; advance X position
        LDA #$09                    ; char 9 = 'I'
        JSR CHRGEN                  ; draw 'I'
        INC XX
        LDA #$16                    ; char 22 = 'V'
        JSR CHRGEN                  ; draw 'V'
        INC XX
        LDA #$05                    ; char 5 = 'E'
        JSR CHRGEN                  ; draw 'E'
        INC XX
        LDA #$13                    ; char 19 = 'S'
        JSR CHRGEN                  ; draw 'S'
        INC XX                      ; position for digit
        LDA YOULIVES                ; get current lives count
        STA SHAPE                   ; lives count = digit to display
        JMP NUMGEN                  ; draw and return

SHOWHITS:
        LDA YOUHITS                 ; $7F
        ASL A
        ASL A
        TAY
        LDA HITBL,Y                 ; $7003
        STA COLOR                   ; $11
        LDA #$09
        STA X                       ; $18
        LDA #$02
        STA Y                       ; $19
        STY YSAVE                   ; $7D
        JSR PLOTS                   ; $703B
        INC Y                       ; $19
        JSR PLOTS                   ; $703B
        LDY YSAVE                   ; $7D
UPDATEYOUZ:
        LDA $7004,Y

; ----------------------------------------------------------------
; UPDATEYOU - Main player update
; Saves current position, handles demo mode AI,
; checks keyboard/joystick input, and clamps to boundaries
; ----------------------------------------------------------------

UPDATEYOU:
        STA COLOR                   ; $11
        LDA #$07
        STA Y                       ; $19
        JSR PLOTS                   ; $703B
        INC Y                       ; $19
        JSR PLOTS                   ; $703B
        LDY YSAVE                   ; $7D
        LDA $7005,Y
        STA COLOR                   ; $11
        LDA #$0C
        STA Y                       ; $19
        JSR PLOTS                   ; $703B
        INC Y                       ; $19
        JMP PLOTS                   ; $703B

L_727D:
        JMP UP                      ; $7318

REDRAW:
        LDA YOUX                    ; $81
        STA TEMPX                   ; $85
        LDA YOUY                    ; $82
        STA TEMPY                   ; $86
        LDA YOUSHP                  ; $8E
        STA TEMPSHP                 ; $87
UPDLFT1:
        LDA DEMO                    ; $88
CHKUD:
        BMI L_727D
        DEC YOUC                    ; $8F
        BNE L_729D
        INC COUNT                   ; $4E
        LDY COUNT                   ; $4E
        LDA $E000,Y
        STA YOUC                    ; $8F
L_729D:
        LDA YOUC                    ; $8F
        AND #$1F
        STA YOUC                    ; $8F
        LDY COUNT                   ; $4E
        LDA $F700,Y
        ROR A
        ROR A
NOFIXX1:
        BMI L_72B0
        INC YOUX                    ; $81
        BNE NOFIXY
L_72B0:
        DEC YOUX                    ; $81
NOFIXY:
        INY
        LDA $F000,Y
        ROR A
        ROR A
NOFIXY1:
        BMI L_72BE
        INC YOUY                    ; $82
        BNE L_72C0
L_72BE:
        DEC YOUY                    ; $82
L_72C0:
        LDA YOUX                    ; $81
        CMP #$05
NOPEFXS:
        BNE L_72C8
        INC YOUX                    ; $81
L_72C8:
        CMP #$91                    ; Ctrl-Q
        BNE L_72CE
        DEC YOUX                    ; $81
L_72CE:
        LDA YOUY                    ; $82
        CMP #$15
        BCS L_72D6
        INC YOUY                    ; $82
L_72D6:
        CMP #$AA                    ; '*' key
        BCC MOVEEND
        DEC YOUY                    ; $82
MOVEEND:
        LDA TEMPX                   ; $85
        CMP YOUX                    ; $81
        BNE L_72E9
        LDA TEMPY                   ; $86
        CMP YOUY                    ; $82
        BNE L_72E9
        RTS

L_72E9:
        LDA TEMPX                   ; $85
        STA X                       ; $18
        LDA TEMPY                   ; $86
        STA Y                       ; $19
        LDA TEMPSHP                 ; $87
        STA SHAPE                   ; $10
        LDA #$00
        STA FLAG                    ; $FE
        LDA #$FF
        STA COLOR                   ; $11
        JSR DRAWSPRITE              ; $736D
        LDA YOUX                    ; $81
        STA X                       ; $18
        LDA YOUY                    ; $82
        STA Y                       ; $19
        LDA YOUSHP                  ; $8E
        STA SHAPE                   ; $10
        LDA #$FF
        STA FLAG                    ; $FE
        LDA #$FF
YOUDIED:
        STA COLOR                   ; $11
        JSR DRAWSPRITE              ; $736D
        RTS


; ----------------------------------------------------------------
; UP - Keyboard dispatch for player movement
; Returns to KBDCHECK for pause toggle handling
; ----------------------------------------------------------------
UP:
        JMP KBDCHECK                ; check for Ctrl-T pause first

; ----------------------------------------------------------------
; KBDDISPATCH - Process movement keys
; W=$D7=Up, S=$D3=Down, J=$CA=Left, K=$CB=Right
; If no movement key, falls through to MOVEEND
; ----------------------------------------------------------------
KBDDISPATCH:
        CMP #$D7                    ; is it 'W' key? (up)
        BEQ DOMOVUP                 ; yes, move up
        CMP #$D3                    ; is it 'S' key? (down)
        BEQ DOMOVDO                 ; yes, move down
        CMP #$CA                    ; is it 'J' key? (left)
        BEQ DOMOVLE                 ; yes, move left
DO:
        CMP #$CB                    ; is it 'K' key? (right)
        BEQ DOMOVRI                 ; yes, move right
        NOP                         ; padding (timing)
        NOP
        NOP
        JMP MOVEEND                 ; no valid key, process movement

; ----------------------------------------------------------------
; Movement handlers - each checks boundary then updates position
; Also sets sprite shape based on direction
; ----------------------------------------------------------------
DOMOVUP:
        LDA YOUY                    ; get current Y position
        CMP #$16                    ; at top boundary? (Y=22)
        BEQ MOVEEND                 ; yes, can't move up
        DEC YOUY                    ; move up (decrease Y)
        LDA #$00                    ; facing up sprite
        STA YOUSHP                  ; set player sprite shape
        JMP MOVEEND                 ; $72DC

; Move down - check bottom boundary (Y=$AA = 170)
DOMOVDO:
        LDA YOUY                    ; get current Y position
        CMP #$AA                    ; at bottom boundary? (Y=170)
        BEQ MOVEEND                 ; yes, can't move down
        INC YOUY                    ; move down (increase Y)
        LDA #$00                    ; facing down sprite (same as up)
        STA YOUSHP                  ; set player sprite shape
        JMP MOVEEND                 ; process movement end

; Move left - check left boundary (X=$03 = 3)
DOMOVLE:
        LDA YOUX                    ; get current X position
NOFIXER1:
        CMP #$03                    ; at left boundary? (X=3)
        BEQ MOVEEND                 ; yes, can't move left
        DEC YOUX                    ; move left (decrease X)
        LDA #$08                    ; facing left sprite (shape $08)
        STA YOUSHP                  ; set player sprite shape
        JMP MOVEEND                 ; process movement end

; Move right - check right boundary (X=$8F = 143)
DOMOVRI:
        LDA YOUX                    ; get current X position
        CMP #$8F                    ; at right boundary? (X=143)
DRAWYOU2:
        BEQ L_736A                  ; yes, can't move right
        INC YOUX                    ; move right (increase X)
        LDA #$08                    ; facing right sprite (shape $08)
        STA YOUSHP                  ; set player sprite shape
L_736A:
        JMP MOVEEND                 ; process movement end

; ----------------------------------------------------------------
; DRAWSPRITE - Draw player sprite with collision detection
; Handles sprite animation (alternates frames based on Y position)
; Checks for collision with food and enemies
; ----------------------------------------------------------------
DRAWSPRITE:
        LDA SHAPE                   ; get current sprite shape
        BNE L_737B                  ; if not 0, use it directly
        LDA Y                       ; get Y coordinate
        LSR A                       ; divide by 4
        LSR A
        BCC L_737B                  ; if even, keep shape 0
        LDA #$04                    ; if odd, use shape 4 (walk frame)
        STA SHAPE                   ; set alternate walk frame
L_737B:
        JSR DRAW                    ; draw sprite with collision check
        LDA REPORT                  ; get collision result
        AND FLAG                    ; mask with collision enable flag
        BNE L_7387                  ; if collision detected, handle it
L_7384:
        JMP HITPROCESS              ; no collision, continue

; Collision detected - check if time expired
L_7387:
        JSR SOUNDTICK               ; tick timer
        BCC L_7393                  ; time left, continue
        ; Time expired - game over
        LDA #$00                    ; clear hits
        STA YOUHITS                 ; player has no health
        JMP GAMEOVER                ; end game

; ----------------------------------------------------------------
; Check if player touched food (bounding box collision)
; Food hitbox extends 14 pixels left/up, 30 pixels right/down
; ----------------------------------------------------------------
L_7393:
        ; Check X bounds: FOODX-14 <= YOUX <= FOODX+30
        LDA FOODX                   ; get food X position
        SBC #$0E                    ; subtract 14 (left edge)
        CMP YOUX                    ; compare with player X
        BCS L_7384                  ; player left of food

        LDA FOODY                   ; get food Y position
        SBC #$08                    ; subtract 8 (top edge)
        CMP YOUY                    ; compare with player Y
        BCS L_7384                  ; player above food

        LDA FOODX                   ; get food X position
        ADC #$1E                    ; add 30 (right edge)
        CMP YOUX                    ; compare with player X
        BCC HITPROCESS              ; player right of food

        LDA FOODY                   ; get food Y position
        ADC #$1E                    ; add 30 (bottom edge)
        CMP YOUY                    ; compare with player Y
        BCC HITPROCESS              ; player below food

        ; Player touched food! Collect it
        JSR ERASESPRITE             ; erase player sprite
        LDA FOODC                   ; get food type/counter
        STA SHAPE                   ; set as sprite shape
        LDA FOODX                   ; get food position
        STA X                       ; set draw X
        LDA FOODY                   ; get food Y
        STA Y                       ; set draw Y
        LDA #$00                    ; black color
        STA COLOR                   ; to erase food
DRAWYOU4A:
        JSR DRAWCMP                 ; erase food sprite
        JSR ERASESPRITE             ; redraw player
        LDA #$7F                    ; white color
        STA COLOR                   ; restore color
        DEC FOODC                   ; decrement food counter
        LDA FOODC                   ; check remaining
        CMP #$14                    ; all food collected? ($14=20)
        BCS L_73DF                  ; no, spawn next food
        ; All food collected - award bonus and finish level
        PLA                         ; clean up stack
        PLA                         ;
        PLA                         ;
        PLA                         ;
        JMP SCOREBONUS              ; award level bonus

; More food remains - add points and spawn next
L_73DF:
        LDA #$50                    ; 50 points per food
        JSR BCDADD                  ; add to BCD score

; ----------------------------------------------------------------
; PLACEFOOD - Place new food item at pseudo-random position
; Uses ROM data for pseudo-random X/Y coordinates
; Food appears within playfield bounds
; ----------------------------------------------------------------
PLACEFOOD:
        LDA FOODC                   ; get food type
        STA SHAPE                   ; set sprite shape
        LDA #$7F                    ; white color
        STA COLOR                   ; set draw color
        INC COUNT                   ; increment random counter
        LDY COUNT                   ; use as index
        ; Generate pseudo-random X position
        LDA $F900,Y                 ; ROM byte for random
        ADC #$14                    ; offset from left edge
        AND #$70                    ; mask to 0-112 range
        ORA #$14                    ; ensure minimum 20
        STA X                       ; set X coordinate
        STA FOODX                   ; save food X position
        ; Generate pseudo-random Y position
        LDA $F000,Y                 ; ROM byte for random
        AND #$7F
        CLC
        ADC #$18
DRAWYOU5:
        STA Y                       ; $19
        STA FOODY                   ; $C3
        JSR DRAW                    ; $7A00
        LDA REPORT                  ; $1F
        BEQ HITPROCESS
        LDA FOODX                   ; $BB
        STA X                       ; $18
        LDA FOODC                   ; $79
        STA SHAPE                   ; $10
        JSR DRAW                    ; $7A00
        JMP PLACEFOOD               ; $73E4

; Food placement done - reset color and return
HITPROCESS:
        LDA #$7F                    ; white color
        STA COLOR                   ; restore draw color
        RTS                         ; return

; ----------------------------------------------------------------
; ERASESPRITE - Erase player sprite at current position
; Uses XOR drawing to toggle sprite off
; ----------------------------------------------------------------
ERASESPRITE:
        LDA YOUSHP                  ; get player sprite shape
        STA SHAPE                   ; set for draw
        LDA #$FF                    ; full white mask
        STA COLOR                   ; set color
        LDA YOUX                    ; get player X
        STA X                       ; set draw X
        LDA YOUY                    ; get player Y
SNOOKHIT1:
        STA Y                       ; set draw Y
        LDA #$00                    ; no collision checking
        STA FLAG                    ; disable collision flag
        JMP DRAWSPRITE              ; XOR-draw erases sprite

; ----------------------------------------------------------------
; HITFINISH - Player was hit by enemy cat
; Decrements hit counter, respawns at random location
; ----------------------------------------------------------------
HITFINISH:
        STX XSAVE                   ; save current index
        DEC YOUHITS                 ; decrement hit points
        BEQ GAMEOVER                ; no hits left = game over
        JSR SHOWHITS                ; update hit display
        LDA FLAG                    ; save collision state
        STA FLAGSAVE                ; for after respawn
        JSR ERASESPRITE             ; erase player sprite

; Respawn player at new random position
HITCONTINUE:
        INC COUNT                   ; increment random counter
        LDY COUNT                   ; use as index
        LDA $F100,Y                 ; ROM byte for random X
        CLC                         ;
        ADC #$0C                    ; offset from left edge
        AND #$7F                    ; mask to playfield
SNOOKDED:
        STA YOUX                    ; set new player X
        LDA $F200,Y                 ; ROM byte for random Y
        AND #$7F                    ; mask to playfield
        CLC                         ;
        ADC #$1E                    ; offset from top
        STA YOUY                    ; set new player Y
        JSR ERASESPRITE             ; draw at new position
        LDA REPORT                  ; $1F
        BEQ L_74AB
        JSR ERASESPRITE             ; $7423
        JMP HITCONTINUE             ; $744A

; ----------------------------------------------------------------
; GAMEOVER - Player lost a life or game ended
; Decrements lives, plays death sound, restarts level or ends game
; ----------------------------------------------------------------
GAMEOVER:
        DEC YOULIVES                ; decrement lives counter
        BNE L_748C                  ; still have lives? continue
STILMOR:
        ; No more lives - game over
        PLA                         ; clean up stack
        PLA                         ; (discard return addresses)
        PLA                         ;
        PLA                         ;
        JSR SHOWHITS                ; update hit display
        JSR SHOWLEVEL               ; update level display
        LDA #$00                    ; clear enemies
        STA NUMCATS                 ; no cats
        LDA #$FF                    ; max Y for sound
        STA Y                       ;
        LDA #$00                    ; min X for sound
        STA X                       ;
        JMP TWOTONEMAIN             ; play game over sound

; Still have lives - continue with death penalty
L_748C:
        PLA                         ; clean up stack
        PLA                         ;
        PLA                         ;
        PLA                         ;
        JSR ERASESPRITE             ; erase player sprite
        JSR SHOWHITS                ; update hit display
        JSR SHOWLEVEL               ; update level display
SNOKKL:
        LDA #$03                    ; reset hits to 3
        STA YOUHITS                 ; full health again
        LDA #$FF                    ; max Y for sound
        STA Y                       ;

; ----------------------------------------------------------------
; DEATHSOUND - Play death/respawn sound effect
; Uses two-tone beep pattern
; ----------------------------------------------------------------
DEATHSOUND:
        LDA #$00                    ; min X for sound
        STA X                       ;
        JSR TWOTONEMAIN             ; play death sound
        JMP LEVELSTART              ; restart level

; Player survived collision - redraw and play hit sound
L_74AB:
        JSR ERASESPRITE             ; erase old sprite
        LDA #$FF                    ; white color
        STA COLOR                   ; set draw color
        LDA YOUSHP                  ; get player sprite
        STA SHAPE                   ; set for draw
        LDA YOUX                    ; get player position
        STA X                       ;
        LDA YOUY                    ;
        STA Y                       ;
        LDA #$00                    ; no collision flag
        STA FLAG                    ;
        JSR DRAWSPRITE              ; draw player
        STA KBDSTRB                 ; clear keyboard strobe
        JSR SOUNDLOOP1              ; play first tone
        JMP SOUNDLOOP2              ; play second tone

; ----------------------------------------------------------------
; Two-tone sound effect generator
; Creates ascending/descending frequency beeps
; X/Y control pitch, loops for duration
; ----------------------------------------------------------------
SOUNDLOOP1:
        LDA #$00                    ; low pitch
SNOKSND3:
        STA X                       ; set first pitch
SNOKSND4:
        LDA #$40                    ; medium pitch
        STA Y                       ; set second pitch
TWOTONEMAIN:
        LDX #$06                    ; 6 outer loop iterations
L_74D8:
        LDY X                       ; get delay from X register
L_74DA:
        DEY                         ; inner delay loop
        BNE L_74DA                  ; wait
        LDA SOUND                   ; check sound enabled
        BMI L_74E4                  ; bit 7 = sound off
        STA SPKR                    ; toggle speaker
L_74E4:
        DEX                         ; next iteration
        BNE L_74D8                  ; continue tone
        LDX #$06                    ; reset for next frequency
L_74E9:
        LDY Y                       ; $19
L_74EB:
        DEY
        BNE L_74EB
        LDA SOUND                   ; $84
        BMI INITCAT
        STA SPKR                    ; $C030

; ----------------------------------------------------------------
; INITCAT - Initialize a new enemy (cat)
; Sets position from PLACESX/PLACESY tables,
; direction to 1 (right), walk counter to 5
; ----------------------------------------------------------------

INITCAT:
        DEX
        BNE L_74E9
        INC X                       ; $18
        DEC Y                       ; $19
        LDA Y                       ; $19
        BNE TWOTONEMAIN
        RTS

SOUNDLOOP2:
        LDX XSAVE                   ; $91
        LDA #$FF
        STA COLOR                   ; $11
        LDA FLAGSAVE                ; $7E
        STA FLAG                    ; $FE

; ----------------------------------------------------------------
; PUTCAT/DRAWCAT - Enemy sprite rendering
; CATRI/CATNX - Cat movement right/next
; STACAT - Start cat movement
; NOWALK - Handle enemy at rest
; ----------------------------------------------------------------

; Jump to draw cat sprite
PUTCAT:
        JMP DRAWCATSPRITE           ; draw cat at current position

; ----------------------------------------------------------------
; GETPLAYERX/GETPLAYERY - Get target X/Y for cat AI
; If cat index X=0: chase player (YOUX/YOUY)
; If cat index X>0: chase food (FOODX/FOODY)
; This makes first cat always chase player, others chase food
; ----------------------------------------------------------------
GETPLAYERX:
        CPX #$00                    ; is this cat #0?
        BEQ L_7515                  ; yes, chase player
        LDA FOODX                   ; no, chase food X
        RTS

L_7515:
        LDA YOUX                    ; return player X
DRAWCAT:
        RTS

GETPLAYERY:
        CPX #$00                    ; is this cat #0?
        BEQ L_751F                  ; yes, chase player
        LDA FOODY                   ; no, chase food Y
        RTS

L_751F:
        LDA YOUY                    ; return player Y
        RTS

; ----------------------------------------------------------------
; CATRI - Initialize cat at numbered spawn position
; Sets position from PLACESX/PLACESY tables
; Direction = 1 (right), walk counter = 5
; ----------------------------------------------------------------
CATRI:
        LDX NUMCATS                 ; get cat index
        LDA #$05                    ; walk counter = 5 frames
CATNX:
        STA CATWALK,X               ; set walk delay
        STA CATUSE,X                ; mark cat as active
        LDA PLACESX,X               ; get spawn X from table
        STA CATX,X                  ; set cat X position
        LDA PLACESY,X               ; get spawn Y from table
STACAT:
        STA CATY,X                  ; set cat Y position
        LDA #$01                    ; direction = right
        STA CATDIR,X                ; set cat direction
        LDA CATX,X                  ; get X for drawing
        STA X                       ; set sprite X
        LDA CATY,X                  ; get Y for drawing
        STA Y                       ; set sprite Y
        JSR CATMOVECHECK            ; draw cat and check
        RTS

; ----------------------------------------------------------------
; CATMOVECHECK - Draw cat sprite based on direction
; If direction bit 0 = 1: facing left (shape $10)
; If direction bit 0 = 0: facing right (shape $0C)
; Uses $20 as color cycle flag
; ----------------------------------------------------------------
CATMOVECHECK:
        LDA CATDIR,X                ; get cat direction
        LSR A                       ; shift bit 0 to carry
        BCC L_754F                  ; if 0, facing right
        LDA #$10                    ; facing left sprite
        STA SHAPE                   ; set sprite shape
NOWALK:
        BNE L_7553                  ; always branch
L_754F:
        LDA #$0C                    ; facing right sprite
        STA SHAPE                   ; set sprite shape
L_7553:
        LDA #$7F                    ; white color
        STA COLOR                   ; set draw color
        STX XSAVE                   ; save cat index
        LDA #$FF                    ; enable color cycling
ZEROX:
        STA $20                     ; set color cycle flag
        JSR DRAW                    ; draw sprite with collision
        LDA #$00                    ; disable color cycling
        STA $20                     ; clear flag
        LDX XSAVE                   ; restore cat index
        RTS

; ----------------------------------------------------------------
; CATSNDHIT - Draw cat with STABW (erase mode, no collision)
; Used when cat needs to be erased/redrawn without collision
; ----------------------------------------------------------------
CATSNDHIT:
        LDA CATDIR,X                ; get cat direction
        LSR A                       ; check direction bit
        BCC L_7572                  ; if 0, facing right
        LDA #$10                    ; facing left sprite
        STA SHAPE
        BNE L_7576                  ; always branch
L_7572:
        LDA #$0C                    ; facing right sprite
        STA SHAPE
L_7576:
        LDA #$7F                    ; white color
        STA COLOR
        STX XSAVE                   ; save cat index
SKIPCAT1:
        LDA #$FF                    ; enable color cycling
        STA $20
        JSR STABW                   ; erase sprite (no collision)
        LDA #$00                    ; disable color cycling
UPCAT1:
        STA $20
        LDX XSAVE                   ; restore cat index
        RTS

; ----------------------------------------------------------------
; Cat AI - Determine movement direction toward target
; Compares cat position with target (player or food)
; Sets CATDIR bits: bit0=left/right, bit1=up, bit2=down
; ----------------------------------------------------------------
L_758A:
        JSR GETPLAYERX              ; get target X position
        CMP CATX,X                  ; compare with cat X
        BMI MOVCAT                  ; target left of cat, move left
        BEQ L_7599                  ; same X, just wait
        LDA #$00                    ; target right of cat
        STA CATDIR,X                ; set direction = right
        BEQ L_75A1
L_7599:
        ; Same X position - set walk delay (pause briefly)
        LDA #$14                    ; walk delay = 20 frames
        STA CATWALK,X               ; pause before next move
MOVCAT:
        ; Target is left of cat - set direction bit 0 (left)
        LDA #$01                    ; direction = left
        STA CATDIR,X                ; set cat direction
L_75A1:
        ; Now compare Y positions for vertical movement
        JSR GETPLAYERY              ; get target Y position
        CMP CATY,X                  ; compare with cat Y
UPCATLE:
        BCC UPNODO                  ; target above cat, move up
UPCATL1:
        BEQ L_75B8                  ; same Y, no vertical move
        ; Target below cat - add "down" bit to direction
        LDA #$04                    ; direction bit: down
        ORA CATDIR,X                ; combine with left/right
        STA CATDIR,X                ; store combined direction
        BNE L_75B8                  ; (always taken)
UPNODO:
        ; Target above cat - add "up" bit to direction
        LDA #$02                    ; direction bit: up
        ORA CATDIR,X                ; combine with left/right
        STA CATDIR,X                ; store combined direction
L_75B8:
        JMP CATDONELOOP             ; proceed to move cat

L_75BB:
        JMP CATHITSND               ; cat hit something - play sound

; ----------------------------------------------------------------
; UPDATECATS - Main cat AI update loop
; Processes all cats, updates positions, checks collisions
; CATDIR bits: 0=left(1)/right(0), 1=up, 2=down
; ----------------------------------------------------------------
UPDATECATS:
        LDX NUMCATS                 ; start with highest cat index
        LDA #$00                    ; clear active flag
        STA FLAG                    ; no cats active yet
UPCATLOOP:
        LDA CATUSE,X                ; is this cat slot active?
        BEQ L_75BB                  ; no, skip to next cat
        LDA CATX,X                  ; save current position
        STA TEMPX                   ; for sprite erase
        LDA CATY,X                  ; get cat Y position
        STA FLAG                    ; mark at least one cat active
        STA TEMPY                   ; save for erase
PLO:
        LDA CATDIR,X                ; save current direction
        STA TEMPSHP                 ; for sprite selection
        LDA CATWALK,X               ; get walk delay counter
        BEQ L_758A                  ; zero = recalculate direction
        DEC CATWALK,X               ; decrement walk delay

; ----------------------------------------------------------------
; CATDONELOOP - Move cat based on direction bits
; Direction bits: bit0=left, bit1=up, bit2=down
; If bit0=0, move right; if bit0=1, move left
; ----------------------------------------------------------------
CATDONELOOP:
        LDA CATDIR,X                ; get direction flags
        LSR A                       ; shift bit0 (left/right) into carry
        BCS L_75E5                  ; carry set = move left
        INC CATX,X                  ; carry clear = move right
        BNE L_75E7                  ; (always taken, skip left)
L_75E5:
        DEC CATX,X                  ; move left (decrement X)
L_75E7:
        LSR A                       ; shift bit1 (up) into carry
        BCC L_75EC                  ; carry clear = no up movement
        DEC CATY,X                  ; move up (decrement Y)
L_75EC:
        LSR A                       ; shift bit2 (down) into carry
        BCC L_75F1                  ; carry clear = no down movement
        INC CATY,X                  ; move down (increment Y)
L_75F1:
        ; Erase cat at old position, draw at new position
        LDA CATDIR,X                ; get new direction
HITSI:
        PHA                         ; save new direction
        ; First, erase cat sprite at old position
        LDA TEMPX                   ; old X position
        STA X                       ; set draw X
        LDA TEMPY                   ; old Y position
        STA Y                       ; set draw Y
        LDA TEMPSHP                 ; old direction (for sprite)
        STA CATDIR,X                ; restore for sprite selection
        JSR CATMOVECHECK            ; erase old sprite (XOR draw)
        ; Now draw cat at new position
        PLA                         ; restore new direction
        STA CATDIR,X                ; set new direction
        LDA CATX,X                  ; new X position
        STA X                       ; set draw X
        LDA CATY,X                  ; new Y position
        STA Y                       ; set draw Y
        JSR CATMOVECHECK            ; draw new sprite (XOR)

        ; Check for boundary collisions (playfield edges)
        LDA CATX,X                  ; check X position
        CMP #$04                    ; left boundary?
        BEQ L_7632                  ; yes, reverse direction
        CMP #$8C                    ; right boundary? ($8C=140)
        BEQ L_7632                  ; yes, reverse direction
        LDA CATY,X                  ; check Y position
        CMP #$14                    ; top boundary? ($14=20)
        BEQ L_7638                  ; yes, reverse vertical
        CMP #$AA                    ; bottom boundary? ($AA=170)
UPCAT1A:
        BEQ L_7638                  ; yes, reverse vertical
        ; Check collision report from sprite draw
        LDA #$02                    ; normal collision type
        STA ASAVE1                  ; save collision type
        LDA REPORT                  ; get collision result
        BEQ CATHITSND               ; no collision, continue
        BPL L_763E                  ; positive = partial overlap
        JMP HITFINISH               ; negative = solid hit (player?)

; Hit left/right boundary - reverse horizontal direction
L_7632:
        LDA #$00                    ; collision type = horizontal edge
        STA ASAVE1                  ; save for direction flip
        BEQ DRAWCATSPRITE           ; (always taken)

; Hit top/bottom boundary - reverse vertical direction
L_7638:
        LDA #$01                    ; collision type = vertical edge
        STA ASAVE1                  ; save for direction flip
        BNE DRAWCATSPRITE           ; (always taken)

; Partial collision - random chance to play sound
L_763E:
        INC COUNT                   ; increment frame counter
        LDY COUNT                   ; use as random seed
        LDA $F000,Y                 ; pseudo-random from ROM
        AND #$03                    ; 1 in 4 chance
        BNE DRAWCATSPRITE           ; 75% skip sound
        ; Play cat bump sound
        LDA CATX,X                  ; get cat position
        STA X                       ; set for redraw
        LDA CATY,X                  ; get cat Y
        STA Y                       ; set for redraw
SNDHIT:
        JSR CATSNDHIT               ; play bump sound
        JMP DRAWCATSPRITE           ; continue to redraw

; Cat didn't hit anything - move to next cat
CATHITSND:
        DEX                         ; next cat index
        BPL L_7662                  ; more cats to process?
SNDHIT1:
        ; All cats processed - check if any were active
        LDA FLAG                    ; any cats moved this frame?
        BEQ L_765F                  ; no cats, award bonus
        RTS                         ; yes, return normally

L_765F:
        JMP SCOREBONUS              ; award bonus for clear level

L_7662:
        JMP UPCATLOOP               ; process next cat

; ----------------------------------------------------------------
; DRAWCATSPRITE - Redraw cat after boundary bounce
; Flips direction based on collision type (ASAVE1)
; Uses CATBTBL to XOR direction bits for bounce effect
; ----------------------------------------------------------------
DRAWCATSPRITE:
        LDA CATX,X                  ; get cat X position
        STA TEMPX                   ; save for redraw
        STA X                       ; set draw X coordinate
        LDA CATY,X                  ; get cat Y position
        STA TEMPY                   ; save for redraw
        STA Y                       ; set draw Y coordinate
        LDA CATDIR,X                ; get current direction
        STA TEMPSHP                 ; save old direction
        LDY ASAVE1                  ; collision type (0=horiz, 1=vert)
        EOR CATBTBL,Y               ; flip appropriate direction bit
        STA CATDIR,X                ; store new direction
        ; Calculate pseudo-random walk delay
        TXA                         ; cat index
        ADC TIME                    ; add time for randomness
        LSR A                       ; divide by 8
        LSR A                       ; for delay variation
        LSR A                       ;
FINBONUS:
        TAY                         ; Y = delay index

; ----------------------------------------------------------------
; ADDSCORE - Set walk delay and play movement sound
; Uses ROM data for pseudo-random delay values
; ----------------------------------------------------------------
ADDSCORE:
        LDA $F800,Y                 ; get pseudo-random value
        AND #$1F                    ; mask to 0-31
        ORA #$05                    ; minimum delay of 5
        STA CATWALK,X               ; set walk delay timer
        STX XSAVE                   ; save cat index
        LDX #$03                    ; 3 sound iterations
L_7690:
        ; Generate variable-pitch sound
        LDA XSAVE                   ; get cat index
        ROL A                       ; shift left with carry
        ASL A                       ; multiply for frequency
        ASL A                       ;
        ASL A                       ;
        EOR COUNT                   ; XOR with counter for variation
        TAY                         ; Y = delay count
L_7699:
        DEY                         ; delay loop
ADDSCORE1:
        BNE L_7699                  ; continue delay
        LDA SOUND                   ; check if sound enabled
BEGIN:
        BMI L_76A3                  ; bit7 set = sound off
        STA SPKR                    ; toggle speaker
L_76A3:
        INC COUNT                   ; increment frame counter
        DEX                         ; next sound iteration
        BNE L_7690                  ; repeat 3 times
        LDX XSAVE                   ; restore cat index
        JMP CATDONELOOP             ; continue processing

; ----------------------------------------------------------------
; SCOREBONUS - Award bonus points after level clear
; Adds 1 point at a time with sound, until time runs out
; ----------------------------------------------------------------
SCOREBONUS:
        LDA #$01                    ; add 1 point
        JSR BCDADD                  ; add to BCD score
        JSR SOUNDTICK               ; play tick sound
        BCS L_76C1                  ; if time expired, done
        JSR SOUNDTICK               ; another tick
        BCS L_76C1                  ; check time
        JSR SOUNDTICK               ; third tick
        BCC SCOREBONUS              ; if time left, loop
L_76C1:
        RTS

; ----------------------------------------------------------------
; BCDADD - Add A to 3-byte BCD score
; Uses SED/CLD for decimal mode arithmetic
; Score bytes: SCORELO($8A), SCOREHI($8B), SCOREHI1($8C)
; Also updates score display via SHOWSCORE
; ----------------------------------------------------------------
BCDADD:
        SED                         ; enable decimal (BCD) mode
        CLC                         ; clear carry for addition
        ADC SCORELO                 ; add A to low byte
        STA SCORELO                 ; store result
        BCC L_76D9                  ; no carry, skip high bytes
        CLC                         ; clear carry for next add
        LDA SCOREHI                 ; get middle byte
        ADC #$01                    ; add carry
BCDADDHI:
        STA SCOREHI                 ; store middle byte
        BCC L_76D9                  ; no carry, done
        LDA SCOREHI1                ; get high byte
        ADC #$01                    ; add carry
        STA SCOREHI1                ; store high byte
L_76D9:
        CLD                         ; disable decimal mode
        JMP SHOWSCORE               ; update score display


; ----------------------------------------------------------------
; Game initialization
; INITLIVES - Set starting lives (3)
; LEVELSTART - Set up screen, enemies, player start position
; Main game loop begins at L_772C (32-frame loop)
;
; Loop structure:
;   Outer: L_772C loads frame counter = $20 (32)
;   Inner: L_772E processes one frame:
;     - Check Ctrl-S (sound toggle) / ESC (pause)
;     - Update enemies (UPDATEENEMIES)
;     - Update player (UPDATEPLAYER)
;     - Difficulty-based speed: easy=2x player, hard=3x enemies
;   After 32 frames: SOUNDTICK, then loop
; ----------------------------------------------------------------

; ----------------------------------------------------------------
; INITLIVES - Initialize lives at game start
; Sets 3 lives and resets paddle counter
; ----------------------------------------------------------------
INITLIVES:
        LDA #$03                    ; 3 starting lives
        STA YOUHITS                 ; set hit counter
        STA PADCOUNT                ; reset paddle counter

; ----------------------------------------------------------------
; LEVELSTART - Initialize level display and enemies
; Draws border, shows score/lives, spawns cats based on level
; ----------------------------------------------------------------
LEVELSTART:
        JSR BORDER                  ; draw screen border
        JSR SHOWSCORE               ; display current score
        JSR SHOWLEVEL               ; display "LIVES" and count
        JSR SHOWHITS                ; display hit indicator
        LDA LEVEL                   ; get current level number
BEGIN1:
        CLC
        ADC #$01                    ; level + 1
        LSR A                       ; divide by 4
        LSR A
        AND #$03                    ; mask to 0-3 cats
        STA NUMCATS                 ; set enemy count
        LDA NUMCATS                 ; get count back
        PHA                         ; save for later

; Initialize each cat (enemy) with position and direction
INITCATLOOP:
        JSR CATRI                   ; spawn a cat at random position
        DEC NUMCATS                 ; next cat
        LDA NUMCATS
        BPL INITCATLOOP             ; loop for all cats
        PLA                         ; restore cat count
        STA NUMCATS

        ; Initialize player starting position
        LDA #$28                    ; starting X = 40
        STA YOUX                    ; set player X
FIXSOUND:
        STA X                       ; also set sprite X
        LDA #$3C                    ; starting Y = 60
        STA YOUY                    ; set player Y
NOKEY:
        STA Y                       ; also set sprite Y
        LDA #$00                    ; facing up sprite
        STA YOUSHP                  ; set player shape
        STA SHAPE                   ; set draw shape
        LDA #$FF                    ; white color
        STA COLOR                   ; set draw color
BEGIN3:
        JSR DRAW                    ; draw player sprite
        LDA #$1B                    ; food type $1B
        STA FOODC                   ; set food counter
        JSR PLACEFOOD               ; place food item
        JSR CATRI                   ; spawn another cat

; ================================================================
; MAIN GAME LOOP
; Runs 32 frames ($20) per outer loop iteration
; Handles keyboard, updates enemies and player
; ================================================================
L_772C:
        LDA #$20                    ; 32 frames per cycle
L_772E:
        STA ASAVE                   ; save frame counter

        ; Check for special keys
        LDA KEYBOARD                ; read keyboard
        CMP #$93                    ; Ctrl-S? (toggle sound)
        BEQ L_7748                  ; yes, toggle sound
        CMP #$9B                    ; ESC? (pause)
        BNE L_774E                  ; no, continue
        ; ESC pressed - pause until keypress
        STA KBDSTRB                 ; clear keyboard strobe
UPEYOU1:
        LDA KEYBOARD                ; wait for keypress
        BPL UPEYOU1                 ; loop until key down
        STA KBDSTRB                 ; clear strobe
        BNE L_774E                  ; continue game

; Toggle sound on/off
L_7748:
        LDA SOUND                   ; get sound flag
        EOR #$80                    ; flip bit 7
        STA SOUND                   ; store new setting

; Check demo mode / exit
L_774E:
        LDA DEMO                    ; are we in demo mode?
        BNE L_7757                  ; yes, skip key exit check
        LDA KEYBOARD                ; check for any keypress
        BMI L_7792                  ; if pressed, exit demo

; Update game state
L_7757:
        JSR UPDATEENEMIES           ; move and draw all cats

        ; Speed control based on level (difficulty)
        LDA LEVEL                   ; get current level
        CMP #$04                    ; level < 4? (easy)
        BCC L_776A                  ; yes, extra player update
        CMP #$0F                    ; level >= 15? (hard)
        BCS L_7773                  ; yes, extra enemy update
        JSR UPDATEPLAYER            ; medium: one player update
        JMP MAINLOOPTIMING          ; $777F

L_776A:
        JSR UPDATEPLAYER            ; $77A1
        JSR UPDATEPLAYER            ; $77A1
        JMP MAINLOOPTIMING          ; $777F

L_7773:
        JSR UPDATEENEMIES           ; $7795
        JSR UPDATEENEMIES           ; $7795
        JSR UPDATEPLAYER            ; $77A1
        JSR UPDATEPLAYER            ; $77A1
MAINLOOPTIMING:
        LDA ASAVE                   ; $FD
        TAY
        DEY
        TYA
        BNE L_772E
        JSR SOUNDTICK               ; $717A
        BCC L_772C
        LDA #$00
        STA YOUHITS                 ; $7F
        JMP GAMEOVER                ; $746F

L_7792:
        JMP $0803

UPDATEENEMIES:
        JSR GETTIMECALC             ; $77AA
        JSR WAIT                    ; $FCA8
        JSR UPDATECATS              ; $75BE
        JMP REDRAW                  ; $7280

UPDATEPLAYER:
        JSR GETTIMECALC             ; $77AA
        JSR WAIT                    ; $FCA8
        JMP REDRAW                  ; $7280

GETTIMECALC:
        LDA LEVEL                   ; $78
        LSR A
        AND #$0F
        EOR #$0E
        ASL A
        CLC
        ADC #$01
        RTS

        STA YOUSHP                  ; $8E
        STA SHAPE                   ; $10
        LDA #$FF
        STA COLOR                   ; $11
        JSR DRAW2                   ; $9300
        LDA #$FF
        STA DEMO                    ; $88
        LDA #$0A
L_77C7:
        STA ASAVE                   ; $FD
        JSR SHOWNUM                 ; $7256
        LDA ASAVE                   ; $FD
        TAY
        DEY
        TYA
        BNE L_77C7
        JSR DEATHSOUND              ; $74A1
L_77D6:
        LDA #$20
L_77D8:
        STA ASAVE                   ; $FD
        LDA KEYBOARD                ; $C000
        CMP #$93                    ; Ctrl-S
        BEQ L_77F2
        CMP #$9B                    ; Ctrl-[
        BNE L_77F8
        STA KBDSTRB                 ; $C010
L_77E8:
        LDA KEYBOARD                ; $C000
        BPL L_77E8
        STA KBDSTRB                 ; $C010
        BNE L_77F8
L_77F2:
        LDA SOUND                   ; $84
        EOR #$80
        STA SOUND                   ; $84
L_77F8:
        JSR PAGEINIT1               ; $786F
        LDA LEVEL                   ; $78
        CMP #$0F
        BCS L_7804
        JSR PAGEINIT2               ; $7880
L_7804:
        DEC YSAVE                   ; $7D
        LDA YSAVE                   ; $7D
        BEQ L_7821
        AND #$1F
        BEQ L_7850
PAGESETUP1:
        LDA ASAVE                   ; $FD
        TAY
        DEY
        TYA
        BNE L_77D8
        JSR DEC2                    ; $715E
        BCC L_77D6
        LDA #$00
        STA YOUHITS                 ; $7F
        JMP PLACEFOOD2              ; $73F4

L_7821:
        LDA FOODC                   ; $79
        BEQ PAGESETUP2
        JSR PAGESETUP3              ; $785C
PAGESETUP2:
        INC $FF
        LDY $FF
        LDA $F000,Y
        CLC
        ADC #$14
        AND #$7F
        STA $7B
        LDA $F200,Y
        AND #$7F
        ADC #$28
        STA $7C
        LDA #$FF
        STA FOODC                   ; $79
        JSR PAGESETUP3              ; $785C
        LDA REPORT                  ; $1F
        BEQ PAGESETUP1
        JSR PAGESETUP3              ; $785C
        JMP PAGESETUP2              ; $7828

L_7850:
        JSR PAGESETUP3              ; $785C
        LDA FOODC                   ; $79
        EOR #$FF
        STA FOODC                   ; $79
        JMP PAGESETUP1              ; $780E

PAGESETUP3:
        LDA #$14
        STA SHAPE                   ; $10
        LDA $7B
        STA X                       ; $18
        LDA $7C
        STA Y                       ; $19
        LDA #$7F
        STA COLOR                   ; $11
        JMP DRAW2                   ; $9300

PAGEINIT1:
        JSR PAGEINITLOOP            ; $789A
        JSR WAIT                    ; $FCA8
        JSR CATHITCHECK             ; $756F
        BCS L_7889
        JSR BCDADDHI                ; $76CF
        JMP REDRAWSCENE             ; $727C

PAGEINIT2:
        JSR PAGEINITLOOP            ; $789A
        JSR WAIT                    ; $FCA8
        JMP REDRAWSCENE             ; $727C

L_7889:
        PLA
        PLA
        LDA #$50
L_788D:
        STA ASAVE                   ; $FD
        JSR BCDADDHI                ; $76CF
        LDA ASAVE                   ; $FD
        TAY
        DEY
        TYA
        BNE L_788D
        RTS

PAGEINITLOOP:
        LDA LEVEL                   ; $78
        LSR A
        AND #$0F
        EOR #$0E
        ASL A
        CLC
        ADC #$01
        RTS

        .BYTE $00
        .BYTE $00
        .BYTE $FF                                  ; |#######|
        .BYTE $FF                                  ; |#######|
        .BYTE $00
        .BYTE $00
        .BYTE $FF                                  ; |#######|
        .BYTE $FF                                  ; |#######|
        .BYTE $00
        .BYTE $00
        .BYTE $FF                                  ; |#######|
        .BYTE $FF                                  ; |#######|
        .BYTE $00
        .BYTE $00
        .BYTE $FF                                  ; |#######|
        .BYTE $FF                                  ; |#######|
        .BYTE $00
        .BYTE $00
        .BYTE $FF                                  ; |#######|
        .BYTE $FF                                  ; |#######|
        .BYTE $00
        .BYTE $00
        .BYTE $FF                                  ; |#######|
        .BYTE $FF                                  ; |#######|
        .BYTE $00
        .BYTE $00
        .BYTE $FF                                  ; |#######|
        .BYTE $FF                                  ; |#######|
        .BYTE $00
        .BYTE $00
        .BYTE $FF                                  ; |#######|
        .BYTE $FF                                  ; |#######|
        .BYTE $00
        .BYTE $00
