; ----------------------------------------------------------------
; Plot vector dispatch table (for page-flipped drawing)
; Routes to appropriate plot routine based on entry point
; Writes to BOTH HGR pages using EOR #$60 trick
; ----------------------------------------------------------------
DRAWVEC:
        JMP PLOTRTS                 ; vector 0: no-op (return)

        JMP PLOTRTS                 ; vector 1: no-op (return)

DRAWVEC_OR:
        JMP PLOTOR                  ; vector 2: OR plot

DRAWVEC_DIR:
        JMP PLOTDIRECT              ; vector 3: direct plot

        JMP PLOTRTS                 ; vector 4: no-op (return)

; ----------------------------------------------------------------
; PLOTDIRECT - Direct write pixel to both HGR pages
; Input: X($18)=X coordinate, Y($19)=Y coordinate, COLOR($11)=color
; Uses HGRLO/HGRHI tables for row address lookup
; Writes to both pages via EOR #$60 (page 1: $2x, page 2: $4x)
; ----------------------------------------------------------------
PLOTDIRECT:
        LDY Y                       ; get Y row
        LDX HGRLO,Y                 ; get HGR address low byte
        LDA HGRHI,Y                 ; get HGR address high byte
        STA TOHI                    ; set pointer high (page 1)
        STX TOLO                    ; set pointer low
        LDA X                       ; get X coordinate
        LSR A                       ; divide by 4
        LSR A                       ; (4 pixels per byte)
        TAY                         ; Y = byte offset in row
        LDA COLOR                   ; get color/pixel pattern
        STA (TOLO),Y                ; write to page 1
        PHA                         ; save color
        LDA TOHI                    ; get page 1 high byte
        EOR #$60                    ; flip to page 2 ($2x↔$4x)
        STA TOHI                    ; point to page 2
        PLA                         ; restore color
        STA (TOLO),Y                ; write to page 2
        RTS

; ----------------------------------------------------------------
; PLOTOR - OR pixel into both HGR pages (additive/non-destructive)
; Same as PLOTDIRECT but ORs with existing screen content
; ----------------------------------------------------------------
PLOTOR:
        LDY Y                       ; get Y row
        LDX HGRLO,Y                 ; get HGR address low byte
        LDA HGRHI,Y                 ; get HGR address high byte
        STA TOHI                    ; set pointer (page 1)
        STX TOLO                    ; set pointer low
        LDA X                       ; get X coordinate
        LSR A                       ; divide by 4
        LSR A                       ; (4 pixels per byte)
        TAY                         ; Y = byte offset in row
        LDA COLOR                   ; get color pattern
        ORA (TOLO),Y                ; OR with existing screen
        STA (TOLO),Y                ; write merged to page 1
        PHA                         ; save merged color
        LDA TOHI                    ; get page 1 high byte
        EOR #$60                    ; flip to page 2
        STA TOHI                    ; point to page 2
        PLA                         ; restore merged color
        STA (TOLO),Y                ; write to page 2
PLOTRTS:
        RTS

; ----------------------------------------------------------------
; HGRLO - Low bytes of HGR row addresses (192 entries)
; Apple II HGR has interleaved memory layout
; Row Y's base address = HGRHI[Y]:HGRLO[Y]
; Pattern: $00 for first 8 rows, $80 for next 8, repeating
; Then $28/$A8 pattern, then $50/$D0 pattern
; ----------------------------------------------------------------
HGRLO:
        .BYTE $00, $00, $00, $00, $00, $00, $00, $00, $80, $80, $80, $80, $80, $80, $80, $80 ; |................................................................................................................|
        .BYTE $00, $00, $00, $00, $00, $00, $00, $00, $80, $80, $80, $80, $80, $80, $80, $80 ; |................................................................................................................|
        .BYTE $00, $00, $00, $00, $00, $00, $00, $00, $80, $80, $80, $80, $80, $80, $80, $80 ; |................................................................................................................|
        .BYTE $00, $00, $00, $00, $00, $00, $00, $00, $80, $80, $80, $80, $80, $80, $80, $80 ; |................................................................................................................|
        .BYTE $28, $28, $28, $28, $28, $28, $28, $28, $A8, $A8, $A8, $A8, $A8, $A8, $A8, $A8 ; |...#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#.|
        .BYTE $28, $28, $28, $28, $28, $28, $28, $28, $A8, $A8, $A8, $A8, $A8, $A8, $A8, $A8 ; |...#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#.|
        .BYTE $28, $28, $28, $28, $28, $28, $28, $28, $A8, $A8, $A8, $A8, $A8, $A8, $A8, $A8 ; |...#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#.|
        .BYTE $28, $28, $28, $28, $28, $28, $28, $28, $A8, $A8, $A8, $A8, $A8, $A8, $A8, $A8 ; |...#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#.|
        .BYTE $50, $50, $50, $50, $50, $50, $50, $50, $D0, $D0, $D0, $D0, $D0, $D0, $D0, $D0 ; |....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#|
        .BYTE $50, $50, $50, $50, $50, $50, $50, $50, $D0, $D0, $D0, $D0, $D0, $D0, $D0, $D0 ; |....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#|
        .BYTE $50, $50, $50, $50, $50, $50, $50, $50, $D0, $D0, $D0, $D0, $D0, $D0, $D0 ; |....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#|

; ----------------------------------------------------------------
; DRAW2 Sprite Engine - Main entry points
; DRAW     - Draw sprite with collision detection (XOR blit)
; CLRSCRN  - Clear hi-res screen to black
; ORPLOT   - OR a pixel onto screen (additive)
; PLOT     - Direct pixel write (overwrites)
; STABW    - Sprite blit for erasing (no collision)
;
; Sprite format: [WIDTH][HEIGHT][WIDTH*HEIGHT pixel bytes]
; Sprite address = (SHAPE | $40) * 256 (page-aligned in HGR)
; Sub-pixel alignment: 4 pre-shifted versions (SHAPE+0..+3)
; Collision detected by ANDing sprite with screen (REPORT)
; ----------------------------------------------------------------
DRAW:
        JMP DRAWIMPL                ; draw with collision check

CLRSCRN:
        JMP CLRSCR2                 ; clear screen

ORPLOT:
        JMP ORPLOTIMPL              ; OR-plot single pixel

PLOT:
        JMP PLOTIMPL                ; direct-write single pixel

STABW:
        JMP ERABW2                  ; erase sprite (no collision)

; ----------------------------------------------------------------
; PLOTIMPL - Single-page pixel write (current draw page)
; Uses HGRLO2/HGRHI2 for current page only
; ----------------------------------------------------------------
PLOTIMPL:
        LDY Y                       ; get Y row
HGRHI:
        LDX HGRLO2,Y                ; get address low byte
        LDA HGRHI2,Y                ; get address high byte
        STA TOHI                    ; set pointer high
        STX TOLO                    ; set pointer low
        LDA X                       ; get X coordinate
        LSR A                       ; divide by 4
        LSR A                       ; (4 pixels per byte)
        TAY                         ; Y = byte offset
        LDA COLOR                   ; get color pattern
        STA (TOLO),Y                ; write to screen
        RTS

; ----------------------------------------------------------------
; ORPLOTIMPL - Single-page OR-plot (current draw page)
; ORs color with existing screen content
; ----------------------------------------------------------------
ORPLOTIMPL:
        LDY Y                       ; get Y row
        LDX HGRLO2,Y                ; get address low byte
        LDA HGRHI2,Y                ; get address high byte
        STA TOHI                    ; set pointer high
        STX TOLO                    ; set pointer low
        LDA X                       ; get X coordinate
        LSR A                       ; divide by 4
        LSR A                       ; (4 pixels per byte)
        TAY                         ; Y = byte offset
        LDA COLOR                   ; get color pattern
        ORA (TOLO),Y                ; OR with existing screen
        STA (TOLO),Y                ; write merged result
        RTS

; ----------------------------------------------------------------
; DRAWIMPL - Main sprite drawing engine with collision
; Reads sprite from (SHAPE | $40) * 256 address
; Uses XOR drawing for toggling sprite on/off
; Collision result stored in REPORT (non-zero = collision)
;
; Sub-pixel alignment: X coordinate mod 4 selects one of
; 4 pre-shifted sprite versions at consecutive pages
; (SHAPE+0 through SHAPE+3)
; ----------------------------------------------------------------
DRAWIMPL:
        LDA #$00                    ; clear collision report
        STA REPORT                  ; no collisions yet

        ; Calculate byte offset for X coordinate
        ; X is in pixels, we need byte offset (divide by 4)
        LDA X                       ; get X pixel coordinate
        LDY #$00                    ; counter for byte position
L_7A45:
        INY                         ; count bytes
        SEC                         ; prepare for subtraction
        SBC #$04                    ; subtract 4 pixels
        BCC L_7A51                  ; went negative, done
        INY                         ; count another byte
        SEC                         ; prepare again
        SBC #$04                    ; subtract 4 more pixels
        BCS L_7A45                  ; still positive, continue
L_7A51:
        ; Calculate color mask offset
        DEY                         ; adjust count
        TYA                         ; get byte count
        AND #$01                    ; odd/even mask
        EOR #$01                    ; flip for color
        CLC                         ; prepare for rotate
        ROR A                       ; rotate into high bits
        ROR A                       ;
        AND $20                     ; mask with screen value
        STA SHPLO                   ; sprite pointer low byte

        ; Select sub-pixel sprite version (0-3)
        LDA X                       ; get X coordinate
        AND #$03                    ; X mod 4 = sub-pixel offset
        CLC                         ;
        ADC SHAPE                   ; add to base shape
        STA SHAPE                   ; final sprite page

        ; Convert X to byte offset
        LDA X                       ; get X coordinate
        LSR A                       ; divide by 4
        LSR A                       ; (4 pixels per byte)
        STA X                       ; store byte offset
        STA XX                      ; save for row loop

        ; Save Y coordinate
        LDA Y                       ; get Y coordinate
        STA YY                      ; save for row loop

        ; Build sprite pointer: (SHAPE | $40) * 256
        LDA SHAPE                   ; get sprite number
        ORA #$40                    ; OR with $40 (HGR page 1 base)
        STA SHPHI                   ; sprite address high byte

        ; Read sprite header: [WIDTH][HEIGHT]
        LDY #$00                    ; offset 0
        LDA (SHPLO),Y               ; read width byte
        STA WIDTH                   ; store sprite width
        INY                         ; offset 1
        LDA (SHPLO),Y               ; read height byte
        STA HEIGHT                  ; store sprite height
        INY                         ; offset 2 (start of data)
        TYA                         ; advance pointer past header
        CLC                         ;
        ADC SHPLO                   ; add 2 to pointer
        STA SHPLO                   ; now points to pixel data
; Row drawing loop - process HEIGHT rows
L_7A8B:
        LDA WIDTH                   ; get sprite width
        STA TEMPWID                 ; save as column counter

        ; Calculate HGR row address from Y coordinate
        LDY YY                      ; get current row
        LDA HGRLO2,Y                ; HGR row low byte (interleaved)
        CLC                         ; prepare for offset add
        ADC X                       ; add byte offset within row
        STA TOLO                    ; screen pointer low byte
        LDA HGRHI2,Y                ; HGR row high byte
        STA TOHI                    ; screen pointer high byte

        ; Column drawing loop - process WIDTH bytes per row
        LDY #$00                    ; start at first column
L_7AA0:
        ; Collision detection: check if sprite overlaps screen
        LDA (SHPLO),Y               ; get sprite byte
        AND COLOR                   ; mask with color
        CMP (TOLO),Y                ; compare with screen
        BEQ L_7AB0                  ; same = no collision
        ; Different pixels - check for actual overlap
        LDA (TOLO),Y                ; get screen byte
        AND (SHPLO),Y               ; AND with sprite
        ORA REPORT                  ; accumulate collision bits
        STA REPORT                  ; non-zero = collision!

L_7AB0:
        ; XOR draw: toggle sprite on/off screen
        LDA (SHPLO),Y               ; get sprite byte
        AND COLOR                   ; mask with color pattern
        EOR (TOLO),Y                ; XOR with screen byte
        STA (TOLO),Y                ; write result back

        INY                         ; next column
        DEC TEMPWID                 ; decrement column counter
        BNE L_7AA0                  ; loop until row complete

        ; Advance to next sprite row
        LDA SHPLO                   ; get sprite pointer
        CLC                         ; prepare for addition
        ADC WIDTH                   ; advance by row width
        STA SHPLO                   ; update pointer
        INC YY                      ; next screen row
        DEC HEIGHT                  ; decrement row counter
        BNE L_7A8B                  ; loop until all rows done
        RTS                         ; return

; ----------------------------------------------------------------
; CLRSCR2 - Clear hi-res screen to black
; Clears all 192 rows ($BF down to $00), 40 bytes per row
; Then sets Apple II soft switches for HGR display
; ----------------------------------------------------------------
CLRSCR2:
        LDA #$00                    ; black color
        STA COLOR                   ; set fill color
        LDA #$BF                    ; start at row 191 (bottom)
        STA Y                       ; set row counter
L_7AD3:
        ; Clear one row, right to left
        LDA #$27                    ; 39 bytes per row (0-39)
        STA X                       ; start at rightmost byte
        LDA X                       ; get byte position
L_7AD9:
        PHA                         ; save byte position
        ASL A                       ; multiply by 4 for pixel X
        ASL A                       ; (convert byte to pixel)
        STA X                       ; set pixel coordinate
        JSR PLOTIMPL                ; write black byte
        PLA                         ; restore byte position
        STA X                       ; put back for next loop
        DEC X                       ; next byte left
        LDA X                       ; check if done
        BPL L_7AD9                  ; loop until row complete

        ; Move to next row up
        DEC Y                       ; previous row
        LDA Y                       ; check if done
        CMP #$FF                    ; wrapped below 0?
        BNE L_7AD3                  ; no, continue clearing

        ; Enable HGR display via soft switches
        STA TXTCLR                  ; graphics mode (not text)
        STA MIXCLR                  ; full screen (no text window)
        STA HIRES                   ; hi-res mode
        STA LOWSCR                  ; display page 1
        RTS                         ; return

; ----------------------------------------------------------------
; ERABW2 - Sprite erase without collision (entry point)
; Same as DRAWIMPL but no collision detection
; Used for erasing sprites before redraw
; ----------------------------------------------------------------
ERABW2:
        LDA #$00                    ; clear report (unused)
        STA REPORT                  ; no collision tracking

        ; Calculate byte offset for X coordinate
        LDA X                       ; get X pixel coordinate
        LDY #$00                    ; counter for byte position
L_7B07:
        INY                         ; count bytes
        SEC                         ; prepare for subtraction
        SBC #$04                    ; subtract 4 pixels
        BCC L_7B13                  ; went negative, done
        INY                         ; count another byte
        SEC                         ; prepare again
        SBC #$04                    ; subtract 4 more pixels
        BCS L_7B07                  ; still positive, continue
L_7B13:
        NOP                         ; timing adjustment
        TYA                         ; get byte count
        AND #$01                    ; odd/even mask
        CLC                         ; prepare for rotate
        ROR A                       ; rotate into high bits
        ROR A                       ;
        AND $20                     ; mask with screen value
        STA SHPLO                   ; sprite pointer low byte

        ; Select sub-pixel sprite version (0-3)
        LDA X                       ; get X coordinate
        AND #$03                    ; X mod 4 = sub-pixel offset
        CLC                         ;
        ADC SHAPE                   ; add to base shape
        STA SHAPE                   ; final sprite page

        ; Convert X to byte offset
        LDA X                       ; get X coordinate
        LSR A                       ; divide by 4
        LSR A                       ; (4 pixels per byte)
        STA X                       ; store byte offset
        STA XX                      ; save for row loop

        ; Save Y coordinate
        LDA Y                       ; get Y coordinate
        STA YY                      ; save for row loop

        ; Build sprite pointer: (SHAPE | $40) * 256
        LDA SHAPE                   ; get sprite number
        ORA #$40                    ; OR with $40 (HGR base)
        STA SHPHI                   ; sprite address high byte

        ; Read sprite width from header
        LDY #$00                    ; offset 0
        LDA (SHPLO),Y               ; read width byte

; ----------------------------------------------------------------
; ERABW - Sprite draw without collision checking
; Simply copies sprite data directly to screen
; Used for background elements (borders, decorations)
; ----------------------------------------------------------------
ERABW:
        STA WIDTH                   ; store sprite width
        INY                         ; offset 1
        LDA (SHPLO),Y               ; read height byte
        STA HEIGHT                  ; store sprite height
        INY                         ; offset 2 (start of data)
        TYA                         ; advance pointer past header
        CLC                         ;
        ADC SHPLO                   ; add 2 to pointer
        STA SHPLO                   ; now points to pixel data

; Row drawing loop (no collision)
L_7B4B:
        LDA WIDTH                   ; get sprite width
        STA TEMPWID                 ; save as column counter

        ; Calculate HGR row address from Y coordinate
        LDY YY                      ; get current row
        LDA HGRLO2,Y                ; HGR row low byte
        CLC                         ; prepare for offset add
        ADC X                       ; add byte offset
        STA TOLO                    ; screen pointer low byte
        LDA HGRHI2,Y                ; HGR row high byte
        STA TOHI                    ; screen pointer high byte

        ; Column drawing loop - direct write (no XOR, no collision)
        LDY #$00                    ; start at first column
L_7B60:
        LDA (SHPLO),Y               ; get sprite byte
        AND COLOR                   ; mask with color pattern
        STA (TOLO),Y                ; write directly to screen
        INY                         ; next column
        DEC TEMPWID                 ; decrement column counter
        BNE L_7B60                  ; loop until row complete

        ; Advance to next sprite row
        LDA SHPLO                   ; get sprite pointer
        CLC                         ; prepare for addition
        ADC WIDTH                   ; advance by row width
        STA SHPLO                   ; update pointer
        INC YY                      ; next screen row
        DEC HEIGHT                  ; decrement row counter
        BNE L_7B4B                  ; loop until all rows done
        RTS                         ; return

; ----------------------------------------------------------------
; DRAWCMP - Compare sprite with screen (collision check only)
; Same setup as DRAW but optimized for collision testing
; ----------------------------------------------------------------
        LDA #$00                    ; clear report
DRAWCMP:
        STA REPORT                  ; no collisions yet
        ; Select sub-pixel sprite version (0-3)
        LDA X                       ; get X coordinate
        AND #$03                    ; X mod 4 = sub-pixel offset
        CLC                         ;
        ADC SHAPE                   ; add to base shape
        STA SHAPE                   ; final sprite page

        ; Convert X to byte offset
        LDA X                       ; get X coordinate
        LSR A                       ; divide by 4
        LSR A                       ; (4 pixels per byte)
        STA X                       ; store byte offset
        STA XX                      ; save for row loop

        ; Save Y coordinate
        LDA Y                       ; get Y coordinate
        STA YY                      ; save for row loop

        ; Build sprite pointer: (SHAPE | $40) * 256
        LDA SHAPE                   ; get sprite number
        ORA #$40                    ; OR with $40 (HGR base)
        STA SHPHI                   ; sprite address high byte
        LDY #$00                    ; offset 0
        STY SHPLO                   ; clear low byte
        LDA (SHPLO),Y               ; read width byte
        STA WIDTH                   ; store sprite width
        INY
        LDA (SHPLO),Y               ; $14
        STA HEIGHT                  ; $1D
        INY
        STY SHPLO                   ; $14
L_7BA8:
        LDA WIDTH                   ; $1C
        STA TEMPWID                 ; $1E
        LDY YY                      ; $1B
        LDA HGRLO2,Y                ; $7BDC
        CLC
        ADC X                       ; $18
        STA TOLO                    ; $16
        LDA HGRHI2,Y                ; $7C9C
        STA TOHI                    ; $17
        LDY #$00
L_7BBD:
        LDA (SHPLO),Y               ; $14
        AND #$7F
        CMP (TOLO),Y                ; $16
        BNE L_7BC9
        LDA COLOR                   ; $11
        STA (TOLO),Y                ; $16
L_7BC9:
        INY
        DEC TEMPWID                 ; $1E
        BNE L_7BBD
        LDA SHPLO                   ; $14
        CLC
        ADC WIDTH                   ; $1C
        STA SHPLO                   ; $14
        INC YY                      ; $1B
        DEC HEIGHT                  ; $1D
        BNE L_7BA8
        RTS

HGRLO2:
        .BYTE $00, $00, $00, $00, $00, $00, $00, $00, $80, $80, $80, $80, $80, $80, $80, $80 ; |................................................................................................................|
        .BYTE $00, $00, $00, $00, $00, $00, $00, $00, $80, $80, $80, $80, $80, $80, $80, $80 ; |................................................................................................................|
        .BYTE $00, $00, $00, $00, $00, $00, $00, $00, $80, $80, $80, $80, $80, $80, $80, $80 ; |................................................................................................................|
        .BYTE $00, $00, $00, $00, $00, $00, $00, $00, $80, $80, $80, $80, $80, $80, $80, $80 ; |................................................................................................................|
        .BYTE $28, $28, $28, $28, $28, $28, $28, $28, $A8, $A8, $A8, $A8, $A8, $A8, $A8, $A8 ; |...#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#.|
        .BYTE $28, $28, $28, $28, $28, $28, $28, $28, $A8, $A8, $A8, $A8, $A8, $A8, $A8, $A8 ; |...#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#.|
        .BYTE $28, $28, $28, $28, $28, $28, $28, $28, $A8, $A8, $A8, $A8, $A8, $A8, $A8, $A8 ; |...#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#.|
        .BYTE $28, $28, $28, $28, $28, $28, $28, $28, $A8, $A8, $A8, $A8, $A8, $A8, $A8, $A8 ; |...#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#.|
        .BYTE $50, $50, $50, $50, $50, $50, $50, $50, $D0, $D0, $D0, $D0, $D0, $D0, $D0, $D0 ; |....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#|
        .BYTE $50, $50, $50, $50, $50, $50, $50, $50, $D0, $D0, $D0, $D0, $D0, $D0, $D0, $D0 ; |....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#|
        .BYTE $50, $50, $50, $50, $50, $50, $50, $50, $D0, $D0, $D0, $D0, $D0, $D0, $D0, $D0 ; |....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#|
        .BYTE $50, $50, $50, $50, $50, $50, $50, $50, $D0, $D0, $D0, $D0, $D0, $D0, $D0, $D0 ; |....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#....#.#|
