; ----------------------------------------------------------------
; Title screen setup
; Draws "SYDNEY DEVELOPMENT CORPORATION PRESENTS" (left over from a 1984 pitch to that company; never shown to players)
;       "SNOOKUMS"
;       "BY JEFF KOFTINOFF"
;       "COPYRIGHT (C)"
;
; Each text block uses different colors and sizes
; COLORMASK sets HGR color pattern (violet/green/orange/blue)
; WIDTH sets horizontal scale, HEIGHT sets vertical scale
; XX/YY set starting position, STRLO/STRHI point to string
; ----------------------------------------------------------------

TITLESETUP:
        .BYTE $9F                                  ; |#####..|
        BEQ L_7FCC           ; (part of data - not real branch)
        ROL A                ; (part of data)
        STA COLORMASK               ; set color pattern

        ; Draw "SYDNEY DEVELOPMENT CORPORATION PRESENTS" (line 1)
        LDA #$01                    ; horizontal scale = 1
        STA WIDTH                   ;
        LDA #$02                    ; vertical scale = 2
        STA HEIGHT                  ;
        LDA #$11                    ; Y position = 17
        STA YY                      ;
        LDA #$09                    ; X position = 9
        STA XX                      ;
        LDA #$56                    ; string at $8156
        STA STRLO                   ;
        LDA #$81                    ;
        STA STRHI                   ;
        JSR RENDERSTR               ; draw the text

        ; Draw "PRESENTS" line (line 2)
        LDA #$2A                    ; orange/blue color pattern
        STA COLORMASK               ;
        LDA #$01                    ; horizontal scale = 1
        STA WIDTH                   ;
        LDA #$02                    ; vertical scale = 2
        STA HEIGHT                  ;
        LDA #$21                    ; Y position = 33
        STA YY                      ;
        LDA #$09                    ; X position = 9
        STA XX                      ;
        LDA #$62                    ; string at $8162
        STA STRLO                   ;
        LDA #$81                    ;
        STA STRHI                   ;
        JSR RENDERSTR               ; draw the text

        ; Draw "BY JEFF KOFTINOFF" (smaller)
        LDA #$55                    ; green color pattern
        STA COLORMASK               ;
        LDA #$01                    ; horizontal scale = 1
        STA WIDTH                   ;
        LDA #$01                    ; vertical scale = 1 (smaller)
        STA HEIGHT                  ;
        LDA #$31                    ; Y position = 49
        STA YY                      ;
        LDA #$0C                    ; X position = 12
        STA XX                      ;
        LDA #$6E                    ; string at $816E
        STA STRLO                   ;
        LDA #$81                    ;
        STA STRHI                   ;
        JSR RENDERSTR               ; draw the text

        ; Draw "SNOOKUMS" title (large, centered)
        LDA #$D5                    ; bright color pattern
        STA COLORMASK               ;
        LDA #$03                    ; horizontal scale = 3 (large)
        STA WIDTH                   ;
        LDA #$09                    ; vertical scale = 9 (large)
L_8089:
        STA HEIGHT                  ;
L_808B:
        LDA #$40                    ; Y position = 64
        STA YY                      ;
        LDA #$04                    ; X position = 4
        STA XX                      ;
        LDA #$77                    ; string at $8177 ("SNOOKUMS")
        STA STRLO                   ;
        LDA #$81                    ;
        STA STRHI                   ;
        JSR RENDERSTR               ; draw the title

        ; Draw copyright notice
        LDA #$FF                    ; white color
        STA COLORMASK               ;
        LDA #$00                    ; horizontal scale = 0 (smallest)
        STA WIDTH                   ;
        LDA #$02                    ; vertical scale = 2
        STA HEIGHT                  ;
        LDA #$8C                    ; Y position = 140
        STA YY                      ; $1B
        LDA #$0B
        STA XX                      ; $1A
        LDA #$80
        STA STRLO                   ; $F0
        LDA #$81
        STA STRHI                   ; $F1
        JSR RENDERSTR               ; $813A
        LDA #$FF
        STA COLORMASK               ; $03
        LDA #$00
        STA WIDTH                   ; $1C
        LDA #$01
        STA HEIGHT                  ; $1D
        LDA #$A0
        STA YY                      ; $1B
        LDA #$0D
        STA XX                      ; $1A
        LDA #$92
        STA STRLO                   ; $F0
        LDA #$81
        STA STRHI                   ; $F1
        JSR RENDERSTR               ; $813A
        LDA #$FF
        STA COLOR                   ; $11
        LDA #$0E
        STA X                       ; $18
        LDA #$00
        STA $13
        STA $12
        LDA #$AA
        STA Y                       ; $19
        LDA #$04
        STA SHAPE                   ; $10
        JSR DRAW2                   ; $9300
        LDA #$14
        STA X                       ; $18
        LDA #$AA
        STA Y                       ; $19
        LDA #$0C
        STA $C0
        .BYTE $83                                  ; |##.....|
        CPX #$83
        BEQ L_8089
        BEQ L_808B
        CPY #$83
        CPY #$83
        CPY #$83
        CPY #$83
        CPY #$83
        CPY #$83
        CPY #$83
        CPY #$83
        BEQ L_80A9
        BEQ L_80AB
        BEQ L_80AD
        .BYTE $80                                  ; |.......|
        .BYTE $80                                  ; |.......|
        LDY #$81
        LDA #$FF
        JSR WAIT                    ; $FCA8
        JSR WAIT                    ; $FCA8
        LDA #$80
        STA STRLO                   ; $F0
        JSR XORSCREEN               ; $81A0
        LDA #$FF
        JSR WAIT                    ; $FCA8
        JSR WAIT                    ; $FCA8
        RTS

; ----------------------------------------------------------------
; RENDERSTR - Render a text string using CHRGEN
; String pointer in STRLO/STRHI, terminated by byte >= $80
; Each character drawn at XX,YY position with WIDTH/HEIGHT scale
; ----------------------------------------------------------------
RENDERSTR:
        LDY #$00                    ; index into string
        LDA (STRLO),Y               ; get next character
        BMI L_814E                  ; bit 7 set = end of string
        JSR CHRGEN                  ; draw character
        ; Advance cursor X position by character width + spacing
        LDA XX                      ; get current X
        SEC                         ; set carry for +1 extra
        ADC WIDTH                   ; add character width
        STA XX                      ; update cursor position
        INC STRLO                   ; point to next character
        BNE RENDERSTR               ; loop (carry wraps handled elsewhere)
L_814E:
        RTS

        .BYTE $13, $19, $04, $0E, $05, $19, $FF    ; |##..#..#..##....#.....###...#.#....#..##..#######|
STR_DEVELOPMENT:
        .BYTE  $04
        .BYTE  $05
