; ----------------------------------------------------------------
; XORSCREEN - Visual dissolve/scramble effect
; XORs each screen byte with its low address byte
; Creates a visual transition effect
; ----------------------------------------------------------------

XORSCREEN:
        LDY #$00
        STY STRLO                   ; $F0
        LDA #$20
        STA STRHI                   ; $F1
L_81A8:
        LDA (STRLO),Y               ; $F0
        EOR STRLO                   ; $F0
        STA (STRLO),Y               ; $F0
        INY
        BNE L_81A8
        INC STRHI                   ; $F1
        LDA STRHI                   ; $F1
        CMP #$40
        BNE L_81A8
        RTS

        .BYTE $10, $08, $08, $04, $04, $00, $1E, $21, $21, $12, $21, $21, $1E, $00, $1C, $22 ; |....#.....#......#.....#......#............####..#....#.#....#..#..#..#....#.#....#..####...........###...#...#.|
        .BYTE $22, $14, $10, $08, $08, $00, $00, $00, $06, $06, $00, $06, $06, $00, $00, $00 ; |.#...#...#.#......#.....#......#.........................##.....##............##.....##.........................|
        .BYTE $06, $06, $00, $06, $06, $02         ; |.##.....##............##.....##.....#.....|
SPRITEDATA:
; Visual binary pattern: | = boundary, # = pixel on, . = pixel off
; 7 bits shown (Apple II HGR format, LSB = leftmost pixel)

        ; --- Character 'SPACE' ---
        .BYTE  $00        ; |.......|
        .BYTE  $24        ; |..#..#.|
        .BYTE  $12        ; |.#..#..|
        .BYTE  $09        ; |#..#...|
        .BYTE  $12        ; |.#..#..|
        .BYTE  $24        ; |..#..#.|
        .BYTE  $00        ; |.......|
        .BYTE  $00        ; |.......|
        ; --- Character 'A' ---
        .BYTE  $00        ; |.......|
        .BYTE  $00        ; |.......|
        .BYTE  $1E        ; |.####..|
        .BYTE  $00        ; |.......|
        .BYTE  $1E        ; |.####..|
        .BYTE  $00        ; |.......|
        .BYTE  $00        ; |.......|
        .BYTE  $00        ; |.......|
        ; --- Character 'B' ---
        .BYTE  $00        ; |.......|
        .BYTE  $09        ; |#..#...|
        .BYTE  $12        ; |.#..#..|
        .BYTE  $24        ; |..#..#.|
        .BYTE  $12        ; |.#..#..|
        .BYTE  $09        ; |#..#...|
        .BYTE  $00        ; |.......|
        .BYTE  $00        ; |.......|
