        LSR CATDIR+2,X              ; $A5
        BPL L_8A0C
        .BYTE $80                                  ; |.......|
        STA SHPHI                   ; $15
        LDY #$00
        STY SHPLO                   ; $14
        LDA YY                      ; $1B
L_8A0C:
        STA Y                       ; $19
        LDA #$10
        STA HEIGHT                  ; $1D
L_8A12:
        LDA XX                      ; $1A
        STA X                       ; $18
        LDA (SHPLO),Y               ; $14
        AND COLORMASK               ; $03
        STA COLOR                   ; $11
        STY TEMP9                   ; $09
        JSR NUMGENPLOT              ; $8A3B
        LDY TEMP9                   ; $09
        INY
        LDA (SHPLO),Y               ; $14
        AND COLORMASK               ; $03
        STA COLOR                   ; $11
        STY TEMP9                   ; $09
        INC X                       ; $18
        JSR NUMGENPLOT              ; $8A3B
        LDY TEMP9                   ; $09
        INY
        INC Y                       ; $19
        DEC HEIGHT                  ; $1D
        BNE L_8A12
        RTS

; ----------------------------------------------------------------
; NUMGENPLOT - Plot one pixel of a number character
; Converts byte position (X) to pixel position (*4) for HGR
; ----------------------------------------------------------------
NUMGENPLOT:
        LDA X                       ; get byte position
        PHA                         ; save it
        ASL A                       ; multiply by 4
        ASL A                       ; (4 pixels per byte)
        STA X                       ; set pixel position
        JSR PLOT                    ; draw pixel
        PLA                         ; restore byte position
        STA X                       ;
        RTS                         ; return

; ----------------------------------------------------------------
; Digit/number bitmap data
; 16 bytes per digit (0-9), 2 bytes per row, 8 rows
