        .BYTE $FF, $FF, $00, $00, $FF, $FF, $00, $00, $08, $FF, $00, $00, $FF, $FF, $00, $00 ; |##############..............##############.................#...#######..............##############..............|
        .BYTE $FF, $FF, $00, $00, $FF, $FF, $00, $00 ; |##############..............##############..............|

; ----------------------------------------------------------------
; CHRGEN - Large character rendering system
; Draws multi-pixel text characters with color patterns
; Font data at $9100: 8 bytes per character, 7 pixels wide
; Character index: 0=space, 1=A, 2=B, ..., 26=Z, 27+=[,\,],^,_
; Input: A = character index, XX/YY = position, HEIGHT = scale
; ----------------------------------------------------------------
CHRGEN:
        ASL A                       ; multiply char index by 8
        ASL A                       ; (8 bytes per character)
        ASL A                       ;
        STA SHPLO                   ; low byte of font data offset
        LDA #$91                    ; font data at $9100
        STA SHPHI                   ; high byte of font address
        LDA XX                      ; get X position
        STA X                       ; set current draw X
        LDA YY                      ; get Y position
        STA Y                       ; set current draw Y
        LDA HEIGHT                  ; get vertical scale
        STA $04                     ; save scale counter
        LDY #$00                    ; start at row 0
        STY $00                     ; initialize row counter

; Draw one row of character pixels
CHRGENROW:
        LDY $00                     ; get current row
        LDA (SHPLO),Y               ; load font bitmap byte
        PHA                         ; save bitmap

; Process each pixel (bit) in the row
CHRGENPIXEL:
        PLA                         ; get bitmap byte
        PHA                         ; save again for loop
        LDX XX                      ; reset X to left edge
        STX X                       ; set draw position
        LDX #$00                    ; pixel counter
        STX TEMP0F                  ; save bit position
        CLC                         ; prepare for shift

L_9029:
        ; Check each bit (pixel) from right to left
        LSR A                       ; shift rightmost bit into carry
        BCC L_903B                  ; bit clear = no pixel
        ; Bit set = draw pixel (foreground)
        STX TEMP9                   ; save pixel counter
        PHA                         ; save remaining bits
        LDA #$FF                    ; full color (foreground)
        STA TEMPA                   ; set color mode
        JSR CHRGENCOLOR             ; apply color and plot
        LDX TEMP9                   ; restore pixel counter
        JMP CHRGENNEXT              ; continue to next pixel

L_903B:
        ; Bit clear = draw background (or skip)
        STX TEMP9                   ; save pixel counter
        PHA                         ; save remaining bits
        LDA #$80                    ; background color
        STA TEMPA                   ; set color mode
        JSR CHRGENCOLOR             ; apply color and plot
        LDX TEMP9                   ; restore pixel counter

CHRGENNEXT:
        INX                         ; next pixel
        PLA                         ; restore bitmap bits
        CPX #$08                    ; processed all 8 pixels?
        BNE L_9029                  ; no, continue loop

        ; Move to next screen row
        INC Y                       ; next Y row
        LDA XX                      ; reset X to left edge
        STA X                       ;
        DEC $04                     ; decrement scale counter
        BNE L_9065                  ; repeat same font row

        ; Scale exhausted - move to next font row
        LDA HEIGHT                  ; reset scale counter
        STA $04                     ;
        PLA                         ; discard stacked bitmap
        INC $00                     ; next font row
        LDA $00                     ; check row count
        CMP #$08                    ; processed all 8 rows?
        BNE L_9068                  ; no, continue
        RTS                         ; done with character

L_9065:
        JMP CHRGENPIXEL             ; repeat current row (scaling)

L_9068:
        JMP CHRGENROW               ; process next font row

; ----------------------------------------------------------------
; CHRGENCOLOR - Apply color alternation for HGR display
; Apple II HGR uses different colors for odd/even columns
; Creates violet/green or blue/orange color patterns
; ----------------------------------------------------------------
CHRGENCOLOR:
        LDA COLORMASK               ; get color mask
        AND #$7F                    ; strip high bit
        BEQ L_9083                  ; black = no alternation
        CMP #$7F                    ; white = no alternation
        BEQ L_9083                  ;
        ; Alternate color based on X position
        LDA X                       ; get current X
        LSR A                       ; check odd/even
        BCC L_9083                  ; even column = normal
        LDA COLORMASK               ; odd column = flip color
        EOR #$7F                    ; invert pattern
        AND TEMPA                   ; apply to current pixel
        JMP CHRGENPLOT              ; go plot it

L_9083:
        LDA COLORMASK               ; use normal color
        AND TEMPA                   ; apply to current pixel

; Plot the pixel to screen
CHRGENPLOT:
        PHA                         ; save color
        LDY WIDTH                   ; get pixel width
        LDA $90BE,Y                 ; get pixel pattern table
        LDY TEMP0F                  ; get bit position
        BEQ L_9095                  ; position 0 = no shift
L_9091:
        ASL A                       ; shift pattern left
        DEY                         ; for bit alignment
        BNE L_9091                  ;
L_9095:
        STA $0E                     ; save pattern
        PLA                         ; restore color
        AND $0E                     ; apply pattern mask
        STA COLOR                   ; set final color
        LDA X                       ; get X position
        PHA                         ; save it
        ASL A                       ; multiply by 4
        ASL A                       ; convert to pixel coord
        STA X                       ; set pixel X
        JSR ORPLOT                  ; OR-plot to screen
        PLA                         ; restore X
        STA X                       ; put back
        LDA TEMP0F                  ; $0F
        PHA
        SEC
        ADC WIDTH                   ; $1C
        AND #$07
        STA TEMP0F                  ; $0F
        PLA
        SEC
        ADC WIDTH                   ; $1C
        AND #$F8
        BEQ L_90BD
        INC X                       ; $18
L_90BD:
        RTS

; =================================================================
; CHRGEN Font Data Reference (located at $9100)
; Font is embedded in the packed data below starting at byte offset +72
; 8 bytes per character, 7 visible bits per row (LSB = leftmost pixel)
; Character mapping: 0=SPACE, 1-26=A-Z, 27-31=symbols
;
; Visual patterns (# = pixel on, . = pixel off):
;
; SPACE (0)     A (1)         B (2)         C (3)         D (4)
; .......       .####..       #####..       .####..       #####..
; .......       ######.       ##..##.       ##..##.       ##..##.
; .......       #....#.       ##.###.       ##..##.       ###.##.
; .......       ######.       ##.##..       ##.....       ###.##.
; .......       #....#.       ##.###.       ##..##.       ###.##.
; .......       ##..##.       ##..##.       ##..##.       ##..##.
; .......       ##..##.       #####..       .####..       #####..
; .......       .......       .......       .......       .......
;
; E (5)         F (6)         G (7)         H (8)         I (9)
; ######.       ######.       .####..       ##.###.       ..###..
; ##..##.       ##..##.       ##..##.       ##.###.       ..###..
; ##.....       ##.....       ##..##.       ##..##.       ..###..
; ######.       ######.       ##.....       ######.       ..###..
; ##.....       ##.....       ##.###.       ##..##.       ..###..
; ##..##.       ###....       ##..##.       ###.##.       ..###..
; ######.       ####...       .####..       ###.##.       ..###..
; .......       .......       .......       .......       .......
;
; J-Z and symbols follow the same 8-byte format
; See level3.s for complete visual reference (identical font)
; =================================================================

        .BYTE $01, $03, $07, $0F, $1F, $3F, $7F, $FF ; |#......##.....###....####...#####..######.##############|
        .BYTE $00, $00, $FF, $FF, $00, $00, $FF, $FF, $00, $00, $FF, $FF, $00, $00, $FF, $FF ; |..............##############..............##############..............##############..............##############|
        .BYTE $00, $00, $FF, $FF, $00, $00, $FF, $FF, $00, $00, $FF, $FF, $00, $00, $FF, $FF ; |..............##############..............##############..............##############..............##############|
        .BYTE $00, $00, $FF, $FF, $00, $00, $FF, $FF, $00, $00, $FF, $FF, $00, $00, $FF, $FF ; |..............##############..............##############..............##############..............##############|
        .BYTE $00, $00, $FF, $FF, $00, $00, $FF, $FF, $00, $00, $00, $00, $00, $00, $00, $00 ; |..............##############..............##############........................................................|
        .BYTE $00, $00, $1E, $3F, $21, $3F, $21, $33, $33, $00, $1F, $33, $3B, $1B, $3B, $33 ; |...............####..######.#....#.######.#....#.##..##.##..##........#####..##..##.##.###.##.##..##.###.##..##.|
        .BYTE $1F, $00, $1E, $33, $33, $03, $33, $33, $1E, $00, $1F, $33, $37, $37, $37, $33 ; |#####..........####..##..##.##..##.##.....##..##.##..##..####.........#####..##..##.###.##.###.##.###.##.##..##.|
        .BYTE $1F, $00, $3F, $33, $03, $3F, $03, $33, $3F, $00, $3F, $33, $03, $3F, $03, $07 ; |#####.........######.##..##.##.....######.##.....##..##.######........######.##..##.##.....######.##.....###....|
        .BYTE $0F, $00, $1E, $33, $33, $03, $3B, $33, $1E, $00, $3B, $3B, $33, $3F, $33, $37 ; |####...........####..##..##.##..##.##.....##.###.##..##..####.........##.###.##.###.##..##.######.##..##.###.##.|
        .BYTE $37, $00, $1C, $1C, $1C, $1C, $1C, $1C, $1C, $00, $BC, $BC, $B8, $B9, $B3, $B7 ; |###.##..........###....###....###....###....###....###....###...........####...####....###.#..###.##..##.###.##.|
        .BYTE $9E, $80, $37, $37, $33, $1F, $33, $37, $37, $00, $0F, $0F, $07, $27, $33, $3B ; |.####.........###.##.###.##.##..##.#####..##..##.###.##.###.##........####...####...###....###..#.##..##.##.###.|
        .BYTE $3F, $00, $3F, $3F, $2D, $2D, $21, $33, $33, $00, $3B, $33, $27, $3F, $39, $33 ; |######........######.######.#.##.#.#.##.#.#....#.##..##.##..##........##.###.##..##.###..#.######.#..###.##..##.|
        .BYTE $37, $00, $1C, $3E, $32, $36, $26, $3E, $1C, $00, $1F, $33, $3B, $1B, $03, $07 ; |###.##..........###...#####..#..##..##.##..##..#..#####...###.........#####..##..##.##.###.##.##..##.....###....|
        .BYTE $07, $00, $0E, $1F, $19, $1B, $13, $3F, $3E, $00, $1F, $33, $33, $1F, $33, $37 ; |###............###...#####..#..##..##.##..##..#..######..#####........#####..##..##.##..##.#####..##..##.###.##.|
        .BYTE $37, $00, $3E, $23, $0F, $1E, $3C, $31, $1F, $00, $3F, $3F, $2D, $2D, $0C, $1E ; |###.##.........#####.##...#.####....####....####.#...##.#####.........######.######.#.##.#.#.##.#...##....####..|
