; ----------------------------------------------------------------
; Page 2 sprite engine (duplicate of STABW/ERABW/DRAW)
; Used for double-buffered rendering
; Draw to back buffer while displaying front buffer
; Uses HGR2LO/HGR2HI tables pointing to HGR page 2 ($4000-$5FFF)
; ----------------------------------------------------------------

; Entry points (same interface as Page 1 engine)
DRAW2:
        JMP DRAWIMPL2               ; draw with collision check

CLRSCRN2:
        JMP CLRSCR2B                ; clear screen

ORPLOT2:
        JMP ORPLOTIMPL2             ; OR-plot single pixel

PLOT2:
        JMP PLOTIMPL2               ; direct-write single pixel

STABW2:
        JMP ERABW2B                 ; erase sprite (no collision)

; ----------------------------------------------------------------
; PLOTIMPL2 - Direct pixel write to HGR page 2
; Same as PLOTIMPL but uses HGR2LO/HGR2HI for page 2
; ----------------------------------------------------------------
PLOTIMPL2:
        LDY Y                       ; get Y row
        LDX HGR2LO,Y                ; get page 2 address low
        LDA HGR2HI,Y                ; get page 2 address high
        STA TOHI                    ; set pointer high
        STX TOLO                    ; set pointer low
        LDA X                       ; get X coordinate
        LSR A                       ; divide by 4
        LSR A                       ; (4 pixels per byte)
        TAY                         ; Y = byte offset
        LDA COLOR                   ; get color pattern
        STA (TOLO),Y                ; write to page 2
        RTS                         ; return

; ----------------------------------------------------------------
; ORPLOTIMPL2 - OR pixel into HGR page 2
; ----------------------------------------------------------------
ORPLOTIMPL2:
        LDY Y                       ; get Y row
        LDX HGR2LO,Y                ; get page 2 address low
        LDA HGR2HI,Y                ; get page 2 address high
        STA TOHI                    ; set pointer high
        STX TOLO                    ; set pointer low
        LDA X                       ; get X coordinate
        LSR A                       ; divide by 4
        LSR A                       ; (4 pixels per byte)
        TAY                         ; Y = byte offset
        LDA COLOR                   ; get color pattern
        ORA (TOLO),Y                ; OR with existing screen
        STA (TOLO),Y                ; write merged result
        RTS                         ; return

; ----------------------------------------------------------------
; DRAWIMPL2 - Sprite drawing for page 2 with collision
; Same algorithm as DRAWIMPL, using page 2 address tables
; ----------------------------------------------------------------
DRAWIMPL2:
        LDA #$00                    ; clear collision report
        STA REPORT                  ; no collisions yet
        ; Select sub-pixel sprite version
        LDA X                       ; get X coordinate
        AND #$03                    ; X mod 4 = sub-pixel offset
        CLC                         ;
        ADC SHAPE                   ; add to base shape
        STA SHAPE                   ; final sprite page
        ; Convert X to byte offset
        LDA X                       ; get X coordinate
        LSR A                       ; divide by 4
        LSR A                       ; (4 pixels per byte)
        STA X                       ; store byte offset
        STA XX                      ; save for row loop
        LDA Y                       ; get Y coordinate
        STA YY                      ; save for row loop
        ; Build sprite pointer: (SHAPE | $40) * 256
        LDA SHAPE                   ; get sprite number
        ORA #$40                    ; OR with $40 (HGR base)
        STA SHPHI                   ; sprite address high byte
        LDY #$00                    ; offset 0
        STY SHPLO                   ; clear low byte
        LDA (SHPLO),Y               ; read width byte
        STA WIDTH                   ; store sprite width
        INY                         ; offset 1
        LDA (SHPLO),Y               ; read height byte
        STA HEIGHT                  ; store sprite height
        INY                         ; offset 2 (start of data)
        STY SHPLO                   ; advance past header
L_936C:
        LDA WIDTH                   ; $1C
        STA TEMPWID                 ; $1E
        LDY YY                      ; $1B
        LDA HGR2LO,Y                ; $943D
        CLC
        ADC X                       ; $18
        STA TOLO                    ; $16
        LDA HGR2HI,Y                ; $94FD
        STA TOHI                    ; $17
        LDY #$00
L_9381:
        LDA (SHPLO),Y               ; $14
        AND COLOR                   ; $11
        CMP (TOLO),Y                ; $16
        BEQ L_9391
        LDA (TOLO),Y                ; $16
        AND (SHPLO),Y               ; $14
        ORA REPORT                  ; $1F
        STA REPORT                  ; $1F
L_9391:
        LDA (SHPLO),Y               ; $14
        AND COLOR                   ; $11
        EOR (TOLO),Y                ; $16
        STA (TOLO),Y                ; $16
        INY
        DEC TEMPWID                 ; $1E
        BNE L_9381
        LDA SHPLO                   ; $14
        CLC
        ADC WIDTH                   ; $1C
        STA SHPLO                   ; $14
        INC YY                      ; $1B
        DEC HEIGHT                  ; $1D
        BNE L_936C
        RTS

CLRSCR2B:
        LDA #$00
        STA COLOR                   ; $11
        LDA #$BF
        STA Y                       ; $19
L_93B4:
        LDA #$27
        STA X                       ; $18
        LDA X                       ; $18
L_93BA:
        PHA
        ASL A
        ASL A
        STA X                       ; $18
        JSR PLOTIMPL2               ; $930F
        PLA
        STA X                       ; $18
        DEC X                       ; $18
        LDA X                       ; $18
        BPL L_93BA
        DEC Y                       ; $19
        LDA Y                       ; $19
        CMP #$FF
        BNE L_93B4
        STA TXTCLR                  ; $C050
        STA MIXCLR                  ; $C052
        STA HIRES                   ; $C057
        STA LOWSCR                  ; $C054
        RTS

ERABW2B:
        LDA #$00
        STA REPORT                  ; $1F
        LDA X                       ; $18
        AND #$03
        CLC
        ADC SHAPE                   ; $10
        STA SHAPE                   ; $10
        LDA X                       ; $18
        LSR A
        LSR A
        STA X                       ; $18
        STA XX                      ; $1A
        LDA Y                       ; $19
        STA YY                      ; $1B
        LDA SHAPE                   ; $10
        ORA #$40
        STA SHPHI                   ; $15
        LDY #$00
        STY SHPLO                   ; $14
        LDA (SHPLO),Y               ; $14
        STA WIDTH                   ; $1C
        INY
        LDA (SHPLO),Y               ; $14
        STA HEIGHT                  ; $1D
        INY
        STY SHPLO                   ; $14
L_940F:
        LDA WIDTH                   ; $1C
        STA TEMPWID                 ; $1E
        LDY YY                      ; $1B
        LDA HGR2LO,Y                ; $943D
        CLC
        ADC X                       ; $18
        STA TOLO                    ; $16
        LDA HGR2HI,Y                ; $94FD
        STA TOHI                    ; $17
        LDY #$00
L_9424:
        LDA (SHPLO),Y               ; $14
        AND COLOR                   ; $11
        STA (TOLO),Y                ; $16
        INY
        DEC TEMPWID                 ; $1E
        BNE L_9424
        LDA SHPLO                   ; $14
        CLC
        ADC WIDTH                   ; $1C
        STA SHPLO                   ; $14
        INC YY                      ; $1B
        DEC HEIGHT                  ; $1D
        BNE L_940F
        RTS

HGR2LO:
        .BYTE $00, $00, $00, $00, $00, $00, $00, $00, $80, $80, $80, $80, $80, $80, $80, $80 ; |................................................................................................................|
        .BYTE $00, $00, $00, $00, $00, $00, $00, $00, $80, $80, $80, $80, $80, $80, $80, $80 ; |................................................................................................................|
        .BYTE $00, $00, $00, $00, $00, $00, $00, $00, $80, $80, $80, $80, $80, $80, $80, $80 ; |................................................................................................................|
        .BYTE $00, $00, $00, $00, $00, $00, $00, $00, $80, $80, $80, $80, $80, $80, $80, $80 ; |................................................................................................................|
